// `var` so it's hoisted and safe to read even before the auth/session code below
// has run (e.g. the module-load-time runDailyResetIfNeeded() call).
var _kdActiveUid = null;
function _nsKey(base) {
  return `${base}__${_kdActiveUid || "anon"}`;
}

function addProofVote(proof, voteType) {
  // voteType: "valid" | "suspicious"
  const votes = { valid: 0, suspicious: 0, ...(proof.votes || {}) };
  votes[voteType] = (votes[voteType] || 0) + 1;
  const flags = proof.flags || [];
  if (votes.suspicious >= 3 && !flags.includes("peer_flagged")) {
    flags.push("peer_flagged");
  }
  return { ...proof, votes, flags };
}

function awardDailyQuestGlobal(questId) {
  try {
    const state = JSON.parse(localStorage.getItem(_nsKey("kd_daily_quests")) || "{}");
    const today = getDailyResetKey();
    const completed = (state.date === today ? state.completed : []) || [];
    if (completed.includes(questId)) return false; // already awarded
    const next = { date: today, completed: [...completed, questId] };
    localStorage.setItem(_nsKey("kd_daily_quests"), JSON.stringify(next));
    window.dispatchEvent(new CustomEvent("kd_quest_award", { detail: { questId } }));
    return true;
  } catch { return false; }
}

// ── Real Action-Based Quests ───────────────────────────────────────────────────

function burnedDaysRemaining(profile) {
  if (!profile?.burnedAt) return 0;
  const burnedAt = new Date(profile.burnedAt);
  const thirtyDays = 30 * 24 * 60 * 60 * 1000;
  const remaining = thirtyDays - (Date.now() - burnedAt.getTime());
  return Math.max(0, Math.ceil(remaining / 86400000));
}


// ── Restored components (stripped during v20 patch) ────────────────────────────

function calcVulturePayout(room, survivorCount) {
  const pot = calcVulturePot(room);
  if (pot === 0 || survivorCount === 0) return { perSurvivor: 0, appFee: 0, pot };

  // Integer math: work in XP points (integers only)
  const appFee = Math.floor((pot * APP_FEE_PCT) / 100);
  const distributable = pot - appFee;
  const base = Math.floor(distributable / survivorCount);
  const remainder = distributable - (base * survivorCount); // dust — goes to app fee

  return {
    pot,
    appFee: appFee + remainder, // absorb dust
    perSurvivor: base,
    distributable,
    survivorCount,
  };
}

function calcVulturePot(room) {
  // Each participant contributes XP_PENALTY_KICK to the pot when burned
  const burned = (room?.kickLog || []).length;
  return burned * XP_PENALTY_KICK; // e.g. 3 kicks × 20 = 60 XP pot
}

function checkBetDeadlines(bets) {
  const now = new Date();
  let changed = false;
  const next = bets.map(b => {
    if (b.status === "active" && b.deadline) {
      const deadlineDate = new Date(b.deadline);
      // deadline is YYYY-MM-DD; end of that day = next day 00:00
      deadlineDate.setDate(deadlineDate.getDate() + 1);
      if (now >= deadlineDate) {
        changed = true;
        return { ...b, status: "pending_confirm", endedAt: new Date().toISOString() };
      }
    }
    return b;
  });
  return { bets: next, changed };
}

function dispatchSocialBurn({ me, following, setFeed, setNotifications, roomName }) {
  const burnMsg = `@${me.userId} has been burned. They failed their sprint after ${me.streak} day${me.streak!==1?"s":""} in "${roomName || "a room"}".`;

  // Post to global feed
  setFeed(prev => [{
    id: Date.now(),
    user: "SYSTEM", init: "SYS", color: "#ef4444",
    time: new Date().toISOString(), type: "system",
    text: burnMsg,
  }, ...prev].slice(0, 200));

  // In-app notification to each follower
  if (following?.length) {
    const notif = {
      id: Date.now() + Math.random(),
      type: "burn",
      message: burnMsg,
      fromUserId: me.userId,
      fromName: me.name,
      timestamp: new Date().toISOString(),
    };
    setNotifications(prev => [notif, ...prev].slice(0, 50));
  }
}

