function getDailyGesture() {
  const GESTURES = [
    "Hold up 2 fingers next to your screen",
    "Show a thumbs up while working",
    "Place a pen or pencil next to your screen",
    "Hold your phone or a small object near the screen",
    "Point at what you're working on",
    "Show your hand open near the keyboard",
    "Make a fist near your screen",
  ];
  const dayIndex = Math.floor(Date.now() / 86400000); // changes every 24h UTC
  return GESTURES[dayIndex % GESTURES.length];
}

