function isBurned(profile) {
  if (!profile?.burnedAt) return false;
  const burnedAt = new Date(profile.burnedAt);
  const thirtyDays = 30 * 24 * 60 * 60 * 1000;
  return (Date.now() - burnedAt.getTime()) < thirtyDays;
}

