function recordFocusMinutes(mins) {
  const p = getQuestProgress();
  const today = getDailyResetKey();
  if (p.date !== today) { p.date = today; p.pomos = 0; p.focusMins = 0; p.tabSwitches = 0; }
  p.focusMins = (p.focusMins || 0) + mins;
  setQuestProgress(p);
  return p.focusMins;
}

function recordPomodoroCompleted() {
  const p = getQuestProgress();
  const today = getDailyResetKey();
  if (p.date !== today) { p.date = today; p.pomos = 0; p.focusMins = 0; p.tabSwitches = 0; }
  p.pomos = (p.pomos || 0) + 1;
  setQuestProgress(p);
  return p.pomos;
}

function recordTabSwitch() {
  const p = getQuestProgress();
  p.tabSwitches = (p.tabSwitches || 0) + 1;
  setQuestProgress(p);
}

function runDailyResetIfNeeded() {
  const today = getDailyResetKey();
  const lastReset = (() => { try { return localStorage.getItem(_nsKey("kd_last_reset")) || ""; } catch { return ""; } })();
  if (lastReset === today) return;
  try {
    // Preserve repeat-daily goals and future-deadline goals; clear their completion status
    const raw = JSON.parse(localStorage.getItem(_nsKey("kd_daily_goals")) || "[]");
    const kept = raw
      .filter(g => g.repeatDaily || (g.deadline && new Date(g.deadline).getTime() > Date.now()))
      .map(g => ({ ...g, completedToday: null, streak: g.repeatDaily ? (g.streak || 0) : 0 }));
    localStorage.setItem(_nsKey("kd_daily_goals"), JSON.stringify(kept));
    localStorage.removeItem(_nsKey("kd_daily_quests"));
    localStorage.removeItem(_nsKey("kd_pomodoro_state"));
    localStorage.removeItem(_nsKey("kd_daily_xp"));
    localStorage.removeItem(_nsKey("kd_accountability_today"));
    localStorage.removeItem(_nsKey("kd_active_timers"));
    localStorage.removeItem(_nsKey("kd_completed_tasks"));
    localStorage.setItem(_nsKey("kd_last_reset"), today);
  } catch {}
}

// Run reset check on module load
runDailyResetIfNeeded();

