function todayKey() { return new Date().toISOString().slice(0, 10); }

function useOnboardingTimer(joinTimestamp, onboardingComplete, onExpire) {
  const [msLeft, setMsLeft] = useState(() => joinTimestamp ? msUntilOnboardingExpiry(joinTimestamp) : 0);
  useEffect(() => {
    if (!joinTimestamp || onboardingComplete) return;
    const id = setInterval(() => {
      const left = msUntilOnboardingExpiry(joinTimestamp);
      setMsLeft(left);
      if (left <= 0) { clearInterval(id); onExpire?.(); }
    }, 1000);
    return () => clearInterval(id);
  }, [joinTimestamp, onboardingComplete]);
  return msLeft;
}

