function ConfettiCannon({ active, origin = { x: 0.5, y: 0.4 } }) {
  const canvasRef = useRef(null);
  const rafRef    = useRef(null);
  const COLORS = ["#F5C800","#f97316","#22c55e","#818cf8","#ec4899","#06b6d4","#fff"];

  useEffect(() => {
    if (!active) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    canvas.width  = window.innerWidth;
    canvas.height = window.innerHeight;

    // Burst particles from origin
    const particles = Array.from({ length: 90 }, () => {
      const angle = (Math.random() * 360) * Math.PI / 180;
      const speed = 6 + Math.random() * 14;
      const size  = 6 + Math.random() * 10;
      return {
        x: canvas.width  * origin.x,
        y: canvas.height * origin.y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 4,
        color: COLORS[Math.floor(Math.random() * COLORS.length)],
        w: size, h: size * (0.4 + Math.random() * 0.6),
        rot: Math.random() * 360, rotV: (Math.random() - 0.5) * 12,
        alpha: 1, shape: Math.random() > 0.5 ? "rect" : "circle",
        gravity: 0.35 + Math.random() * 0.2,
      };
    });

    let frame = 0;
    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      let alive = false;
      for (const p of particles) {
        if (p.alpha <= 0.02) continue;
        alive = true;
        p.x  += p.vx;
        p.y  += p.vy;
        p.vy += p.gravity;
        p.vx *= 0.99;
        p.rot += p.rotV;
        if (frame > 40) p.alpha = Math.max(0, p.alpha - 0.018);
        ctx.save();
        ctx.globalAlpha = p.alpha;
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot * Math.PI / 180);
        ctx.fillStyle = p.color;
        if (p.shape === "circle") {
          ctx.beginPath();
          ctx.arc(0, 0, p.w / 2, 0, Math.PI * 2);
          ctx.fill();
        } else {
          ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
        }
        ctx.restore();
      }
      frame++;
      if (alive) rafRef.current = requestAnimationFrame(draw);
      else ctx.clearRect(0, 0, canvas.width, canvas.height);
    }
    rafRef.current = requestAnimationFrame(draw);
    return () => { if (rafRef.current) cancelAnimationFrame(rafRef.current); };
  }, [active]);

  if (!active) return null;
  return (
    <canvas ref={canvasRef} style={{
      position: "fixed", inset: 0, zIndex: 9997, pointerEvents: "none",
      width: "100vw", height: "100vh",
    }} />
  );
}

// XP number that counts up à la Duolingo

function GoalProofButton({ goal, onProofUploaded, T }) {
  const fileRef = useRef();
  const [uploading, setUploading] = useState(false);

  async function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    // Simulate upload — in production, upload to storage and get URL
    await new Promise(r => setTimeout(r, 600));
    const fakeUrl = URL.createObjectURL(file);
    onProofUploaded(goal.id, fakeUrl);
    setUploading(false);
  }

  if (goal.proofUrl) {
    return (
      <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
        <img src={goal.proofUrl} alt="proof" style={{ width: 32, height: 32, borderRadius: 7, objectFit: "cover", border: `1px solid ${T.border}` }} />
        <span style={{ fontSize: 11, color: T.successText, fontWeight: 600, display:"inline-flex", alignItems:"center", gap:3 }}><KDCheck size={11}/>Proof</span>
      </div>
    );
  }

  return (
    <>
      <input ref={fileRef} type="file" accept="image/*" style={{ display: "none" }} onChange={handleFile} />
      <button
        onClick={() => fileRef.current?.click()}
        disabled={uploading}
        style={{
          display: "flex", alignItems: "center", gap: 5,
          background: "transparent", border: `1px solid ${T.border}`,
          borderRadius: 7, padding: "5px 10px", cursor: "pointer",
          fontSize: 11, fontWeight: 600, color: T.textMuted, fontFamily: "inherit",
          transition: "all 0.15s",
        }}
      >
        {uploading ? "⏳" : ""} {uploading ? "Uploading…" : "Add proof"}
      </button>
    </>
  );
}

