// The full XP celebration overlay (Duolingo-style)

function XPCountUp({ from = 0, to, duration = 900, color = SHARED.yellow, size = 64 }) {
  const [val, setVal] = useState(from);
  useEffect(() => {
    const start = performance.now();
    const diff = to - from;
    function step(now) {
      const p = Math.min(1, (now - start) / duration);
      // ease out cubic
      const ease = 1 - Math.pow(1 - p, 3);
      setVal(Math.round(from + diff * ease));
      if (p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }, [from, to, duration]);
  return (
    <span style={{
      fontSize: size, fontWeight: 900, color,
      fontFamily: "'Geist','Plus Jakarta Sans','Inter',system-ui,sans-serif",
      letterSpacing: -2, lineHeight: 1,
      textShadow: `0 0 48px ${color}aa, 0 0 96px ${color}44`,
    }}>{val > 0 ? "+" : ""}{val}</span>
  );
}

// Streak fire pulse

// ── Global Error Boundary — prevents full white-screen crashes ────────────────
class ErrorBoundary extends Component {
  constructor(props) { super(props); this.state = { hasError: false, error: null }; }
  static getDerivedStateFromError(error) { return { hasError: true, error }; }
  componentDidCatch(error, info) { try { console.error("[KD ErrorBoundary]", error, info); } catch {} }
  render() {
    if (!this.state.hasError) return this.props.children;
    return (
      <div style={{ minHeight: "100vh", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", background: "#0f0f13", color: "#f4f4f8", fontFamily: "system-ui", gap: 16, padding: 32, textAlign: "center" }}>
        <div style={{ fontSize: 32 }}>⚡</div>
        <div style={{ fontWeight: 700, fontSize: 18 }}>Something went wrong</div>
        <div style={{ fontSize: 13, color: "#9ca3af", maxWidth: 380 }}>{String(this.state.error?.message || "Unexpected error")}</div>
        <button onClick={() => { this.setState({ hasError: false, error: null }); }} style={{ marginTop: 8, padding: "10px 24px", background: "#f5c800", color: "#000", border: "none", borderRadius: 8, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>Try again</button>
      </div>
    );
  }
}

