const _localDB = {};
function _putDoc(col,id,data){
  if(!_localDB[col])_localDB[col]={};_localDB[col][id]={...data};
  // Persist certain collections to localStorage too
  const lsKey="kd_"+col;
  if(col==="roomParticipants"||col==="rooms"||col==="proofs"||col==="challenges"){
    const store=lsGet(lsKey)||{};store[id]={...data};lsSet(lsKey,store);
  }
}
function _getDoc(col,id){
  if(_localDB[col]?.[id])return _localDB[col][id];
  const lsKey="kd_"+col;const lsStore=lsGet(lsKey);
  return lsStore?.[id]||null;
}
function _query(col,filters=[],order=null,lim=100){
  let rows=[...Object.values(_localDB[col]||{})];
  // Also merge localStorage rows for persistent collections
  const lsStore=lsGet("kd_"+col);
  if(lsStore){
    for(const[id,row]of Object.entries(lsStore)){
      if(!_localDB[col]?.[id])rows.push(row);
    }
  }
  for(const[f,op,v]of filters){if(op==="==")rows=rows.filter(r=>r[f]===v);}
  return rows.slice(0,lim);
}

