function calcRank(xp=0){for(let i=RANK_TIERS.length-1;i>=0;i--){if((xp||0)>=RANK_TIERS[i].minXP)return RANK_TIERS[i].label;}return"Newcomer";}
// ── Scalable level curve (linear: 50 XP per level) ──────────────────────────
function xpForLevel(level=1){return((Math.max(1,Math.floor(level||1))-1)*50);}
