// fbGetNotifications imported from api.jsx
async function fbAddNotification(userId, type, data = {}) {
  if (!userId) return null;
  const id = "notif_" + Date.now() + "_" + Math.random().toString(36).slice(2,7);
  const notif = { id, userId, recipientId: userId, type, read: false, createdAt: new Date().toISOString(), ...data };
  const all = _getNotifsStore();
  all[id] = notif;
  // Keep max 200 per user
  const userNotifs = Object.values(all).filter(n => n.userId === userId || n.recipientId === userId);
  if (userNotifs.length > 200) {
    const toDelete = userNotifs.sort((a,b) => new Date(a.createdAt) - new Date(b.createdAt)).slice(0, userNotifs.length - 200);
    toDelete.forEach(n => delete all[n.id]);
  }
  _saveNotifsStore(all);
  // Dispatch event so live NotificationsView can react
  try { window.dispatchEvent(new CustomEvent("kd_notif", { detail: notif })); } catch {}
  return id;
}
