async function fbUpdateStreak(uid){const users=_getUsersStore();const u=users[uid];if(!u)return{ok:false};const today=todayStr();if(isSameUTCDay(u.lastSubmissionDate,today))return{ok:true,streak:u.streak||0,wasReset:false,alreadyToday:true};const gap=u.lastSubmissionDate?daysBetween(u.lastSubmissionDate,today):1;const newStreak=gap===1?(u.streak||0)+1:1;users[uid].streak=newStreak;users[uid].lastSubmitDate=today;users[uid].lastSubmissionDate=today;_saveUsersStore(users);return{ok:true,streak:newStreak,wasReset:gap>1};}
async function addXP(uid,amount,{dateKey=null,eventKey="proof"}={}){if(!uid||!amount||amount<=0)return{ok:false,error:"Invalid"};const users=_getUsersStore();const u=users[uid];if(!u)return{ok:false,error:"Not found"};const dk=dateKey?`xp_${eventKey}_${dateKey}`:null;if(dk&&u.xpAwardedKeys?.[dk])return{ok:false,error:"Already awarded"};const newXP=(u.xp||0)+amount;users[uid].xp=newXP;users[uid].rank=calcRank(newXP);users[uid].level=calcLevel(newXP);users[uid].league=calcLeague(newXP);if(dk)users[uid].xpAwardedKeys={...(u.xpAwardedKeys||{}),[dk]:true};_saveUsersStore(users);return{ok:true,newXP,newRank:calcRank(newXP),newLevel:calcLevel(newXP)};}

// ══════════════════════════════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════════════════════════════
// XP ECONOMY GUARD — prevents XP farming through repeated/duplicate actions.
// Every non-proof XP award (chat activity, room joins, follows, badges,
// quests, goals, bets, vulture claims, etc.) passes through checkXPEconomy()
// first. Awards are bucketed by "reason"; each bucket has a daily cap and a
// minimum cooldown between awards. State is persisted per-user so it survives
// reloads and can't be reset by refreshing the page. Only *meaningful*
// progress (capped, cooled-down, deduplicated) ever produces XP.
// LS_XP_LEDGER, XP_DAILY_CAPS, XP_COOLDOWNS moved to src/constants/gameConfig.js
// and src/constants/storageKeys.js
// ══════════════════════════════════════════════════════════════════════════════

function _getXPLedger(uid) {
  const all = _safeGet(LS_XP_LEDGER);
  const today = todayStr();
  let entry = all[uid];
  if (!entry || entry.date !== today) {
    entry = { date: today, counts: {}, lastTimes: (entry && entry.lastTimes) || {}, onceKeys: (entry && entry.onceKeys) || {} };
  }
  return { all, entry };
}
function _saveXPLedger(all, uid, entry) {
  all[uid] = entry;
  _safeSet(LS_XP_LEDGER, all);
}

// Maps a specific reason string (e.g. "quest_streak", "badge_3-Day") to its
// shared bucket (e.g. "quest", "badge") for cap purposes.
function _xpBucket(reason) {
  if (!reason) return "default";
  if (reason.startsWith("quest_")) return "quest";
  if (reason.startsWith("badge_")) return "badge";
  if (reason.startsWith("goal")) return "goal";
  if (reason.startsWith("bet") || reason.toLowerCase().includes("challenge")) return "bet";
  return reason;
}

// Returns true if this XP award is allowed right now, and records it.
// `onceKey` (optional) makes an award permanently one-time per user
// (e.g. a specific badge, a specific quest-for-the-day) regardless of caps.
function checkXPEconomy(uid, reason, onceKey = null) {
  if (!uid) return true; // no persisted guard possible — caller's other checks still apply
  const { all, entry } = _getXPLedger(uid);
  const now = Date.now();

  // Badges are one-time achievements — the badge name itself is a permanent
  // dedup key so re-earning the same badge (e.g. after a streak resets and
  // climbs back up) can never re-award XP.
  if (!onceKey && reason && reason.startsWith("badge_")) onceKey = reason;

  if (onceKey) {
    if (entry.onceKeys[onceKey]) { _saveXPLedger(all, uid, entry); return false; }
    entry.onceKeys[onceKey] = now;
  }

  const bucket = _xpBucket(reason);
  const cooldown = XP_COOLDOWNS[bucket] ?? XP_COOLDOWNS.default;
  const cap = XP_DAILY_CAPS[bucket] ?? XP_DAILY_CAPS.default;

  const last = entry.lastTimes[reason] || 0;
  if (now - last < cooldown) { _saveXPLedger(all, uid, entry); return false; }

  const count = entry.counts[bucket] || 0;
  if (count >= cap) { _saveXPLedger(all, uid, entry); return false; }

  entry.counts[bucket] = count + 1;
  entry.lastTimes[reason] = now;
  _saveXPLedger(all, uid, entry);
  return true;
}

function resetInactiveStreaks(userData){if(!userData)return userData;const today=todayStr();const last=userData.lastSubmissionDate||userData.lastSubmitDate;if(!last||last===today)return userData;const gap=daysBetween(last,today);if(gap<=1)return userData;const newMissed=Math.min((userData.missedDays??0)+Math.min(gap-1,3),3);return{...userData,missedDays:newMissed,streak:newMissed>=3?0:userData.streak,kickStatus:newMissed>=3?"kicked":newMissed>=2?"warned":newMissed>=1?"flagged":"ok",warned:newMissed>=2,kickedFromRoom:newMissed>=3};}
// fbFollowUser, fbUnfollowUser imported from api.jsx
async function fbFollow(uid,targetInit){return fbFollowUser(uid,targetInit);}
async function fbUnfollow(uid,targetInit){return fbUnfollowUser(uid,targetInit);}
async function fbActivateGrace(uid,{days,xpCost,newXP}){const users=_getUsersStore();if(!users[uid])return{ok:false};users[uid].xp=newXP??Math.max(0,(users[uid].xp||0)-(xpCost||0));users[uid].graceActive=true;_saveUsersStore(users);return{ok:true};}
// ══════════════════════════════════════════════════════════════════════════════
// SAFETY & MODERATION BACKEND
// All data stored in localStorage under kd_safety_* keys.
// On a real Supabase backend, each function becomes a DB write with RLS.
// ══════════════════════════════════════════════════════════════════════════════

// LS_REPORTS, LS_BLOCKS, LS_BANS, LS_SUSPENSIONS, LS_AUDIT, LS_MOD_NOTES,
// LS_APPEALS, LS_RATE moved to src/constants/safetyConfig.js

function _safeGet(key){try{return JSON.parse(localStorage.getItem(key)||"{}");}catch{return {};}}
function _safeSet(key,v){try{localStorage.setItem(key,JSON.stringify(v));}catch{}}
function _safeGetArr(key){try{return JSON.parse(localStorage.getItem(key)||"[]");}catch{return[];}}
function _safeSetArr(key,v){try{localStorage.setItem(key,JSON.stringify(v));}catch{}}

// ── Audit log — every moderation action is permanently recorded ───────────────
function _writeAudit(action, actorId, targetId, detail = {}) {
  try {
    const logs = _safeGetArr(LS_AUDIT);
    logs.push({ id: "aud_" + Date.now() + "_" + Math.random().toString(36).slice(2,6), action, actorId, targetId, detail, ts: new Date().toISOString() });
    // Cap at 2000 entries; trim oldest
    if (logs.length > 2000) logs.splice(0, logs.length - 2000);
    _safeSetArr(LS_AUDIT, logs);
  } catch {}
}

// ── Rate limiter — prevents report spam / message flood ──────────────────────
// Returns true if action is allowed, false if rate-limited.
function _checkRateLimit(actorId, action, maxPerWindow = 10, windowMs = 60000) {
  if (!actorId) return false;
  const key = `${actorId}:${action}`;
  const store = _safeGet(LS_RATE);
  const now = Date.now();
  const entry = store[key] || { count: 0, windowStart: now };
  // Reset window if expired
  if (now - entry.windowStart > windowMs) { entry.count = 0; entry.windowStart = now; }
  if (entry.count >= maxPerWindow) {
    _writeAudit("rate_limited", actorId, action, { count: entry.count });
    return false;
  }
  entry.count++;
  store[key] = entry;
  _safeSet(LS_RATE, store);
  return true;
}

// ══════════════════════════════════════════════════════════════════════════════
// ANTI-RAID / ANTI-SPAM: mutes, slow mode, room flood + bot-behavior detection
// LS_MUTES, LS_SLOWMODE, LS_MSG_TIMES moved to src/constants/safetyConfig.js
// ══════════════════════════════════════════════════════════════════════════════

// ── Mute — lighter than a suspension: blocks chat only, account stays active ─
async function fbMuteUser(targetUid, moderatorUid, minutes, reason) {
  if (!targetUid || !reason) return { ok: false };
  const mutes = _safeGet(LS_MUTES);
  const expiresAt = new Date(Date.now() + minutes * 60000).toISOString();
  mutes[targetUid] = { targetUid, moderatorUid: moderatorUid || "SYSTEM", reason, minutes, expiresAt, mutedAt: new Date().toISOString(), active: true };
  _safeSet(LS_MUTES, mutes);
  _writeAudit("mute", moderatorUid || "SYSTEM", targetUid, { minutes, reason, expiresAt });
  return { ok: true, expiresAt };
}
async function fbUnmuteUser(targetUid, moderatorUid) {
  const mutes = _safeGet(LS_MUTES);
  if (mutes[targetUid]) { mutes[targetUid].active = false; mutes[targetUid].unmutedAt = new Date().toISOString(); }
  _safeSet(LS_MUTES, mutes);
  _writeAudit("unmute", moderatorUid || "SYSTEM", targetUid, {});
  return { ok: true };
}
function fbGetMute(uid) {
  const mutes = _safeGet(LS_MUTES);
  const m = mutes[uid];
  if (!m || !m.active) return null;
  if (new Date(m.expiresAt) < new Date()) {
    m.active = false;
    _safeSet(LS_MUTES, mutes);
    return null;
  }
  return m;
}
function fbIsMuted(uid) { return !!fbGetMute(uid); }

// ── Room slow mode — temporarily requires N seconds between messages from
// the SAME user in a room. Can be set manually (mod action) or auto-applied
// when fbCheckRoomFlood() detects a coordinated message burst.
async function fbSetRoomSlowMode(roomId, seconds, minutes, reason, moderatorUid = "SYSTEM") {
  if (!roomId) return { ok: false };
  const slow = _safeGet(LS_SLOWMODE);
  const expiresAt = new Date(Date.now() + (minutes || 5) * 60000).toISOString();
  slow[roomId] = { roomId, seconds: seconds || 5, expiresAt, reason, setBy: moderatorUid, setAt: new Date().toISOString(), active: true };
  _safeSet(LS_SLOWMODE, slow);
  _writeAudit("slow_mode_enabled", moderatorUid, roomId, { seconds, minutes, reason });
  return { ok: true, expiresAt, seconds: slow[roomId].seconds };
}
async function fbClearRoomSlowMode(roomId, moderatorUid = "SYSTEM") {
  const slow = _safeGet(LS_SLOWMODE);
  if (slow[roomId]) { slow[roomId].active = false; }
  _safeSet(LS_SLOWMODE, slow);
  _writeAudit("slow_mode_cleared", moderatorUid, roomId, {});
  return { ok: true };
}
// Returns { active: bool, seconds, expiresAt, reason } for the room, auto-expiring.
function fbGetRoomSlowMode(roomId) {
  const slow = _safeGet(LS_SLOWMODE);
  const s = slow[roomId];
  if (!s || !s.active) return { active: false };
  if (new Date(s.expiresAt) < new Date()) {
    s.active = false;
    _safeSet(LS_SLOWMODE, slow);
    return { active: false };
  }
  return { active: true, seconds: s.seconds, expiresAt: s.expiresAt, reason: s.reason };
}

// ── Room flood detection (anti-raid) ──────────────────────────────────────────
// Tracks every posted message's timestamp + sender per room. If too many
// messages arrive from too many distinct senders in a short window — the
// signature of a coordinated raid — slow mode is auto-enabled for the room.
// ROOM_FLOOD_MSG_COUNT, ROOM_FLOOD_WINDOW_MS, ROOM_FLOOD_MIN_SENDERS,
// ROOM_FLOOD_SLOWMODE_SECONDS, ROOM_FLOOD_SLOWMODE_MINUTES moved to
// src/constants/safetyConfig.js

function fbRecordRoomMessage(roomId, senderId) {
  if (!roomId || !senderId) return;
  try {
    const all = _safeGet(LS_MSG_TIMES);
    const now = Date.now();
    const log = (all[roomId] || []).filter(m => now - m.ts < ROOM_FLOOD_WINDOW_MS);
    log.push({ senderId, ts: now });
    all[roomId] = log;
    _safeSet(LS_MSG_TIMES, all);
    if (log.length >= ROOM_FLOOD_MSG_COUNT) {
      const distinctSenders = new Set(log.map(m => m.senderId)).size;
      if (distinctSenders >= ROOM_FLOOD_MIN_SENDERS) {
        const current = fbGetRoomSlowMode(roomId);
        if (!current.active) {
          fbSetRoomSlowMode(roomId, ROOM_FLOOD_SLOWMODE_SECONDS, ROOM_FLOOD_SLOWMODE_MINUTES, "Auto: message flood detected (possible raid)", "SYSTEM");
          _writeAudit("raid_detected", "SYSTEM", roomId, { messages: log.length, distinctSenders, windowMs: ROOM_FLOOD_WINDOW_MS });
        }
      }
    }
  } catch {}
}

// ── Bot-like behavior detection ───────────────────────────────────────────────
// Real users can't sustain machine-speed message intervals. If a user's last
// few messages all arrived faster than humanly possible (sub-1s, repeatedly),
// flag them and apply a short mute. This catches scripted/bot flooding even
// when each individual message would pass the per-window rate limit.
// LS_BOT_TIMES, BOT_MIN_INTERVAL_MS, BOT_STRIKE_THRESHOLD, BOT_MUTE_MINUTES
// moved to src/constants/safetyConfig.js

// Returns { flagged: bool, muted: bool } — records the timestamp as a side effect.
function fbCheckBotBehavior(senderUid) {
  if (!senderUid) return { flagged: false, muted: false };
  try {
    const all = _safeGet(LS_BOT_TIMES);
    const now = Date.now();
    const rec = all[senderUid] || { lastTs: 0, streak: 0 };
    const interval = now - rec.lastTs;
    if (rec.lastTs && interval < BOT_MIN_INTERVAL_MS) {
      rec.streak = (rec.streak || 0) + 1;
    } else {
      rec.streak = 0;
    }
    rec.lastTs = now;
    all[senderUid] = rec;
    _safeSet(LS_BOT_TIMES, all);
    if (rec.streak >= BOT_STRIKE_THRESHOLD) {
      rec.streak = 0;
      all[senderUid] = rec;
      _safeSet(LS_BOT_TIMES, all);
      fbMuteUser(senderUid, "SYSTEM", BOT_MUTE_MINUTES, "Auto: bot-like message timing detected");
      _writeAudit("bot_behavior_detected", "SYSTEM", senderUid, { intervalMs: interval, muteMinutes: BOT_MUTE_MINUTES });
      return { flagged: true, muted: true };
    }
    return { flagged: false, muted: false };
  } catch { return { flagged: false, muted: false }; }
}

// ── Real fbAddReport — stores evidence, creates reviewable case ───────────────
async function fbAddReport(reporterUid, targetUserId, reason, detail = "", evidence = {}) {
  if (!reporterUid || !targetUserId || !reason) return { ok: false, error: "Missing fields." };
  // Prevent self-report
  if (reporterUid === targetUserId) return { ok: false, error: "Cannot report yourself." };
  // Rate limit: 5 reports per hour per reporter
  if (!_checkRateLimit(reporterUid, "report", 5, 3600000)) return { ok: false, error: "Too many reports. Please wait before submitting another." };

  const id = "rpt_" + Date.now() + "_" + Math.random().toString(36).slice(2,7);
  const report = {
    id, reporterUid, targetUserId, reason,
    detail: (detail || "").slice(0, 1000), // cap detail length
    evidence: {
      messageId: evidence.messageId || null,
      messageText: evidence.messageText ? evidence.messageText.slice(0, 500) : null,
      imageUrl: evidence.imageUrl || null,
      roomId: evidence.roomId || null,
      roomName: evidence.roomName || null,
      timestamp: evidence.timestamp || new Date().toISOString(),
    },
    status: "pending",  // pending | reviewed | actioned | dismissed
    createdAt: new Date().toISOString(),
    reviewedAt: null,
    reviewedBy: null,
    actionTaken: null,
    moderatorNote: null,
    // Child safety escalation flag
    isHighPriority: [
      "Child safety concern", "Grooming", "Sharing personal info",
      "Attempting to move off-platform", "Sexual content", "Threats"
    ].includes(reason),
  };

  const reports = _safeGet(LS_REPORTS);
  reports[id] = report;
  _safeSet(LS_REPORTS, reports);
  _writeAudit("report_filed", reporterUid, targetUserId, { reportId: id, reason });

  // Auto-escalate child safety reports
  if (report.isHighPriority) {
    _writeAudit("child_safety_escalation", "SYSTEM", targetUserId, { reportId: id, reason });
    // Flag target user for immediate review
    const users = _getUsersStore();
    if (users[targetUserId]) {
      users[targetUserId].flaggedForReview = true;
      users[targetUserId].flaggedAt = new Date().toISOString();
      users[targetUserId].flagReason = reason;
      _saveUsersStore(users);
    }
  }

  // Auto-suspend if user accumulates 5+ pending reports
  const allReports = Object.values(reports).filter(r => r.targetUserId === targetUserId && r.status === "pending");
  if (allReports.length >= 5) {
    await fbSuspendUser(targetUserId, "SYSTEM", 24, "Auto-suspended: 5+ pending reports awaiting review.");
  }

  return { ok: true, id };
}

// ── Get reports (for admin/mod view) ─────────────────────────────────────────
function fbGetReports({ status = null, targetUserId = null, reporterUid = null } = {}) {
  let reports = Object.values(_safeGet(LS_REPORTS));
  if (status) reports = reports.filter(r => r.status === status);
  if (targetUserId) reports = reports.filter(r => r.targetUserId === targetUserId);
  if (reporterUid) reports = reports.filter(r => r.reporterUid === reporterUid);
  return reports.sort((a, b) => {
    // High-priority first, then by date
    if (a.isHighPriority !== b.isHighPriority) return a.isHighPriority ? -1 : 1;
    return new Date(b.createdAt) - new Date(a.createdAt);
  });
}

// ── Update report (moderator action) ─────────────────────────────────────────
function fbUpdateReport(reportId, moderatorUid, { status, actionTaken, moderatorNote }) {
  const reports = _safeGet(LS_REPORTS);
  if (!reports[reportId]) return { ok: false, error: "Report not found." };
  reports[reportId] = {
    ...reports[reportId],
    status: status || reports[reportId].status,
    actionTaken: actionTaken || reports[reportId].actionTaken,
    moderatorNote: moderatorNote || reports[reportId].moderatorNote,
    reviewedAt: new Date().toISOString(),
    reviewedBy: moderatorUid,
  };
  _safeSet(LS_REPORTS, reports);
  _writeAudit("report_reviewed", moderatorUid, reports[reportId].targetUserId, { reportId, status, actionTaken });
  return { ok: true };
}

// ── Block system — bidirectional: blocked user cannot see blocker ─────────────
async function fbBlockUser(blockerUid, blockedUid, reason = "") {
  if (!blockerUid || !blockedUid) return { ok: false };
  if (blockerUid === blockedUid) return { ok: false };
  const blocks = _safeGet(LS_BLOCKS);
  const key = `${blockerUid}:${blockedUid}`;
  blocks[key] = { blockerUid, blockedUid, reason, createdAt: new Date().toISOString() };
  _safeSet(LS_BLOCKS, blocks);
  _writeAudit("block", blockerUid, blockedUid, { reason });
  return { ok: true };
}
async function fbUnblockUser(blockerUid, blockedUid) {
  const blocks = _safeGet(LS_BLOCKS);
  delete blocks[`${blockerUid}:${blockedUid}`];
  _safeSet(LS_BLOCKS, blocks);
  _writeAudit("unblock", blockerUid, blockedUid, {});
  return { ok: true };
}
function fbIsBlocked(blockerUid, targetUid) {
  const blocks = _safeGet(LS_BLOCKS);
  // Check both directions
  return !!(blocks[`${blockerUid}:${targetUid}`] || blocks[`${targetUid}:${blockerUid}`]);
}
function fbGetBlockList(uid) {
  const blocks = _safeGet(LS_BLOCKS);
  return Object.values(blocks).filter(b => b.blockerUid === uid).map(b => b.blockedUid);
}

// fbBanUser, fbUnbanUser, fbIsBanned, fbSuspendUser, fbIsSuspended imported from api.jsx
function fbGetSuspension(uid) {
  const sups = _safeGet(LS_SUSPENSIONS);
  return sups[uid] || null;
}

// ── Warn user ─────────────────────────────────────────────────────────────────
async function fbWarnUser(targetUid, moderatorUid, reason, reportId = null) {
  if (!targetUid || !reason) return { ok: false };
  const users = _getUsersStore();
  if (!users[targetUid]) return { ok: false };
  const warnings = (users[targetUid].moderationWarnings || []);
  warnings.push({ reason, reportId, issuedBy: moderatorUid, issuedAt: new Date().toISOString() });
  users[targetUid].moderationWarnings = warnings;
  _saveUsersStore(users);
  _writeAudit("warn", moderatorUid, targetUid, { reason, warningCount: warnings.length });
  // Auto-suspend on 3rd warning
  if (warnings.length >= 3) await fbSuspendUser(targetUid, "SYSTEM", 48, "Auto-suspended after 3 moderation warnings.");
  return { ok: true, warningCount: warnings.length };
}

// ── Moderator notes ───────────────────────────────────────────────────────────
function fbAddModNote(targetUid, moderatorUid, note) {
  const notes = _safeGet(LS_MOD_NOTES);
  if (!notes[targetUid]) notes[targetUid] = [];
  notes[targetUid].push({ note: note.slice(0, 500), moderatorUid, createdAt: new Date().toISOString() });
  _safeSet(LS_MOD_NOTES, notes);
  _writeAudit("mod_note", moderatorUid, targetUid, { note: note.slice(0, 100) });
  return { ok: true };
}
function fbGetModNotes(targetUid) {
  const notes = _safeGet(LS_MOD_NOTES);
  return notes[targetUid] || [];
}

// ── Appeal system ─────────────────────────────────────────────────────────────
async function fbSubmitAppeal(uid, type, reason, detail) {
  if (!uid || !type || !reason) return { ok: false };
  if (!_checkRateLimit(uid, "appeal", 2, 86400000)) return { ok: false, error: "You can only submit 2 appeals per day." };
  const appeals = _safeGet(LS_APPEALS);
  const id = "apl_" + Date.now();
  appeals[id] = { id, uid, type, reason, detail: (detail||"").slice(0,1000), status: "pending", submittedAt: new Date().toISOString(), reviewedAt: null, reviewedBy: null, outcome: null };
  _safeSet(LS_APPEALS, appeals);
  _writeAudit("appeal_submitted", uid, uid, { type, reason });
  return { ok: true, id };
}
function fbGetAppeals({ uid = null, status = null } = {}) {
  let appeals = Object.values(_safeGet(LS_APPEALS));
  if (uid) appeals = appeals.filter(a => a.uid === uid);
  if (status) appeals = appeals.filter(a => a.status === status);
  return appeals.sort((a,b) => new Date(b.submittedAt) - new Date(a.submittedAt));
}
function fbReviewAppeal(appealId, moderatorUid, outcome, note) {
  const appeals = _safeGet(LS_APPEALS);
  if (!appeals[appealId]) return { ok: false };
  appeals[appealId] = { ...appeals[appealId], status: "reviewed", outcome, reviewedBy: moderatorUid, reviewedAt: new Date().toISOString(), moderatorNote: note };
  _safeSet(LS_APPEALS, appeals);
  _writeAudit("appeal_reviewed", moderatorUid, appeals[appealId].uid, { outcome });
  return { ok: true };
}

// ── Audit log getter ──────────────────────────────────────────────────────────
function fbGetAuditLog({ targetId = null, actorId = null, action = null, limit = 200 } = {}) {
  let logs = _safeGetArr(LS_AUDIT);
  if (targetId) logs = logs.filter(l => l.targetId === targetId || l.actorId === targetId);
  if (actorId) logs = logs.filter(l => l.actorId === actorId);
  if (action) logs = logs.filter(l => l.action === action);
  return logs.sort((a,b) => new Date(b.ts) - new Date(a.ts)).slice(0, limit);
}

// ── Privacy: strip PII from public user objects ────────────────────────────────
// CRITICAL: fbGetAllUsers was returning full records including email+passwordHash.
// This wrapper ensures only safe public fields are ever exposed to the frontend.
// _SAFE_PUBLIC_FIELDS moved to src/constants/safetyConfig.js
function _sanitizeUser(u) {
  if (!u) return null;
  const out = {};
  for (const k of _SAFE_PUBLIC_FIELDS) { if (k in u) out[k] = u[k]; }
  return out;
}

// ── Grooming / off-platform / PII pattern detection ──────────────────────────
// _GROOMING_PATTERNS moved to src/constants/safetyConfig.js
// Returns { flagged: bool, patterns: string[] }
function detectGroomingPatterns(text) {
  if (!text) return { flagged: false, patterns: [] };
  const matched = _GROOMING_PATTERNS.filter(p => p.test(text)).map(p => p.source.slice(0, 40));
  return { flagged: matched.length > 0, patterns: matched };
}

// ── Duplicate / spam content detection ───────────────────────────────────────
const _msgHistory = {}; // senderId → last N message fingerprints
function detectSpam(senderId, text) {
  if (!senderId || !text) return false;
  const fp = text.trim().toLowerCase().replace(/\s+/g, " ").slice(0, 100);
  const hist = _msgHistory[senderId] || [];
  const dupes = hist.filter(h => h === fp);
  if (dupes.length >= 2) return true; // same message 3+ times
  hist.push(fp);
  if (hist.length > 10) hist.shift();
  _msgHistory[senderId] = hist;
  return false;
}
