// ── Claude API ─────────────────────────────────────────────────────────────────
async function callClaude(messages, system = "", maxTokens = 600) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 15000); // 15s timeout
  try {
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ model: "claude-sonnet-4-20250514", max_tokens: maxTokens, system, messages }),
      signal: controller.signal,
    });
    clearTimeout(timeout);
    if (!res.ok) return "";
    const data = await res.json();
    return data.content?.[0]?.text || "";
  } catch { clearTimeout(timeout); return ""; }
}

async function moderateImage(base64Data, mediaType = "image/jpeg") {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 12000); // 12s timeout
  try {
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "claude-sonnet-4-20250514",
        max_tokens: 200,
        messages: [{
          role: "user",
          content: [
            { type: "image", source: { type: "base64", media_type: mediaType, data: base64Data } },
            { type: "text", text: "Review this image for content policy. It is allowed UNLESS it contains: explicit nudity, pornographic content, racist imagery, gore/extreme violence, or symbols of hate. Respond ONLY with valid JSON: {\"safe\": true/false, \"reason\": \"one sentence explanation\"}" }
          ]
        }],
        system: "You are a content moderator. Be permissive — only reject genuinely harmful content. Regular photos, selfies, screenshots, work, fitness, food, animals — all fine. Return only JSON."
      }),
      signal: controller.signal,
    });
    clearTimeout(timeout);
    if (!res.ok) return { safe: true, reason: "Moderation unavailable — proof accepted." };
    const data = await res.json();
    const text = data.content?.[0]?.text || '{"safe":true,"reason":"Image approved"}';
    return JSON.parse(text.replace(/```json|```/g, "").trim());
  } catch { clearTimeout(timeout); return { safe: true, reason: "Moderation unavailable — proof accepted." }; }
}

function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    if (!file || !(file instanceof Blob)) { reject(new Error("Invalid file")); return; }
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result;
      if (typeof result !== "string") { reject(new Error("FileReader result not string")); return; }
      const parts = result.split(",");
      resolve(parts.length > 1 ? parts[1] : parts[0]);
    };
    reader.onerror = () => reject(new Error("FileReader error"));
    reader.readAsDataURL(file);
  });
}

