// ═══════════════════════════════════════════════════════════════════════════
// ── Sequential animation queue + wave transition overlay ─────────────────────
// A strict FIFO queue ensures only ONE animation plays at a time across the
// whole app — no overlapping transitions. Each queued item triggers a
// solid-color wave that sweeps across the screen and returns to normal.
// ═══════════════════════════════════════════════════════════════════════════
const AnimationQueueCtx = createContext({ playWave: () => {} });
const useAnimationQueue = () => useContext(AnimationQueueCtx);

// WAVE_COLORS moved to src/constants/theme.js

function AnimationQueueProvider({ children }) {
  const [queue, setQueue] = useState([]); // [{ id, color }]
  const [current, setCurrent] = useState(null); // { id, color }
  const playingRef = useRef(false);

  const playWave = useCallback((colorKey = "create") => {
    const color = WAVE_COLORS[colorKey] || colorKey || WAVE_COLORS.create;
    setQueue(prev => [...prev, { id: `${Date.now()}_${Math.random().toString(36).slice(2,6)}`, color }]);
  }, []);

  // Process queue strictly one item at a time — no overlapping waves
  useEffect(() => {
    if (playingRef.current) return;
    if (queue.length === 0) return;
    const next = queue[0];
    playingRef.current = true;
    setCurrent(next);

    // Wave sweeps in, across, and out, then returns to normal — ~650ms total
    const t = setTimeout(() => {
      setCurrent(null);
      setQueue(prev => prev.slice(1));
      playingRef.current = false;
    }, 650);

    return () => clearTimeout(t);
  }, [queue]);

  return (
    <AnimationQueueCtx.Provider value={{ playWave }}>
      {children}
      {current && (
        <div
          key={current.id}
          aria-hidden="true"
          className="kd-wave-overlay"
          style={{ background: current.color }}
        />
      )}
    </AnimationQueueCtx.Provider>
  );
}

