    disappointed: { body:"#94A3B8", face:"#64748B", eye:"#1a1a2e", shine:"#fff", brow:"#1a1a2e", mouth:"#475569",cheek:"#CBD5E1", bg:"#F1F5F9" },
    encouraging:  { body:"#10B981", face:"#059669", eye:"#1a1a2e", shine:"#fff", brow:"#1a1a2e", mouth:"#fff",   cheek:"#6EE7B7", bg:"#ECFDF5" },
