// ── KD Medal — bronze/silver/gold medals ─────────────────────────────────────
function KDMedal({ size = 24, tier = "gold", animate = false }) {
  const cols = {
    gold:   { rim:"#FFB830", face:"#FDE68A", ribbon:["#FF6B35","#FF8C1A"] },
    silver: { rim:"#94A3B8", face:"#E2E8F0", ribbon:["#64748B","#94A3B8"] },
    bronze: { rim:"#B45309", face:"#FDE68A", ribbon:["#92400E","#B45309"] },
  }[tier] || { rim:"#FFB830", face:"#FDE68A", ribbon:["#FF6B35","#FF8C1A"] };
  const label = { gold:"1", silver:"2", bronze:"3" }[tier] || "1";
  return (
    <svg width={size} height={size} viewBox="0 0 32 32" fill="none" style={{ flexShrink:0, animation: animate ? "kd-bounce 0.6s ease-in-out" : "none", display:"inline-block" }}>
      <rect x="13" y="2" width="3" height="10" rx="1.5" fill={cols.ribbon[0]} />
      <rect x="16" y="2" width="3" height="10" rx="1.5" fill={cols.ribbon[1]} />
      <circle cx="16" cy="21" r="10" fill={cols.rim} />
      <circle cx="16" cy="21" r="8" fill={cols.face} />
      <text x="16" y="26" textAnchor="middle" fontSize="11" fontWeight="900" fill={cols.rim} fontFamily="system-ui">{label}</text>
      <circle cx="12" cy="16" r="1.8" fill="white" opacity="0.5" />
    </svg>
  );
}

// ── KD Confetti burst (particle effect) ───────────────────────────────────────
function KDConfetti({ active = true, count = 12 }) {
  if (!active) return null;
  const pieces = Array.from({length: count}, (_, i) => {
    const angle = (i / count) * 360;
    const dist = 28 + (i % 3) * 10;
    const x = 50 + dist * Math.cos((angle * Math.PI) / 180);
    const y = 50 + dist * Math.sin((angle * Math.PI) / 180);
    const colors = ["#FFB830","#FF6B35","#FF3CAC","#4F8EF7","#10B981","#7C3AED"];
    return { x, y, color: colors[i % colors.length], r: 2 + (i % 3), delay: (i * 0.05).toFixed(2) };
  });
  return (
    <svg width="100" height="100" viewBox="0 0 100 100" fill="none" style={{ position:"absolute", top:"50%", left:"50%", transform:"translate(-50%,-50%)", pointerEvents:"none", zIndex:100 }}>
      {pieces.map((p, i) => (
        <circle key={i} cx={p.x} cy={p.y} r={p.r} fill={p.color}
          style={{ animation: `kd-confetti-fall 0.8s ${p.delay}s ease-out forwards`, opacity:0 }} />
      ))}
    </svg>
  );
}

// ── KD XP Popup — floating XP gain indicator ──────────────────────────────────
function KDXPPopup({ value, visible, style: sx = {} }) {
  if (!visible) return null;
  return (
    <div style={{ position:"absolute", top:0, left:"50%", transform:"translateX(-50%)", animation:"kd-xp-rise 1.2s ease-out forwards", pointerEvents:"none", zIndex:200, display:"flex", alignItems:"center", gap:4, background:"#1E40AF", color:"white", borderRadius:100, padding:"3px 10px", fontSize:13, fontWeight:800, boxShadow:"0 2px 12px rgba(59,130,246,0.5)", ...sx }}>
      <KDXPOrb size={16} />+{value} XP
    </div>
  );
}

// ── KD Rank Icon — maps rank id → custom icon ─────────────────────────────────
function KDRankIcon({ rank = "newcomer", size = 24, animate = false }) {
  const map = {
    newcomer: <KDSeedling size={size} animate={animate} />,
    bronze:   <KDMedal size={size} tier="bronze" animate={animate} />,
    silver:   <KDMedal size={size} tier="silver" animate={animate} />,
    gold:     <KDMedal size={size} tier="gold" animate={animate} />,
    diamond:  <KDDiamond size={size} animate={animate} />,
    legend:   <KDTrophy size={size} gold animate={animate} />,
  };
  return map[rank] || <KDSeedling size={size} />;
}

// ── KD Streak Icon — maps streak milestone → flame/bolt/diamond/crown ─────────
function KDStreakIcon({ days = 0, size = 24, animate = false }) {
  if (days >= 60) return <KDCrown size={size} animate={animate} />;
  if (days >= 30) return <KDTrophy size={size} gold animate={animate} />;
  if (days >= 14) return <KDDiamond size={size} animate={animate} />;
  if (days >= 7)  return <KDBolt size={size} animate={animate} color="#EAB308" />;
  return <KDFlame size={size} animate={animate} />;
}

