// ── KD Notification icon mapper ────────────────────────────────────────────────
function KDNotifIcon({ type = "default", size = 22, animate = false }) {
  if (type === "proof") return <KDCheck size={size} animate={animate} />;
  if (type === "kick")  return <KDSkull size={size} animate={animate} />;
  if (type === "challenge" || type === "challenge_accepted") return <KDSwords size={size} animate={animate} />;
  if (type === "follow") return <KDEye size={size} animate={animate} />;
  if (type === "reward") return <KDTrophy size={size} gold animate={animate} />;
  return <KDBell size={size} animate={animate} />;
}

// ── KD League dot — maps league → coloured orb ───────────────────────────────
function KDLeagueDot({ league = "Bronze", size = 10 }) {
  const colors = { Bronze:"#B45309", Silver:"#64748B", Gold:"#F59E0B", Elite:"#7C3AED" };
  return <span style={{ width:size, height:size, borderRadius:"50%", background: colors[league] || "#6b7280", display:"inline-block", flexShrink:0 }} />;
}

// ── KD Kick/Warn/Grace icons ──────────────────────────────────────────────────
function KDKickIcon({ type = "kick", size = 18 }) {
  if (type === "kick")  return <KDSkull size={size} />;
  if (type === "warn")  return <KDShield size={size} color="#F59E0B" inner="!" />;
  if (type === "grace") return <KDCheck size={size} />;
  return <KDBell size={size} />;
}

// ── KD Badge icon by name ─────────────────────────────────────────────────────
function KDBadgeIcon({ name = "", size = 28, animate = false }) {
  const n = name.toLowerCase();
  if (n.includes("streak") && n.includes("10"))  return <KDFlame size={size} animate={animate} />;
  if (n.includes("streak") && n.includes("30"))  return <KDDiamond size={size} animate={animate} />;
  if (n.includes("streak") && n.includes("60"))  return <KDCrown size={size} animate={animate} />;
  if (n.includes("streak"))                       return <KDFlame size={size} animate={animate} />;
  if (n.includes("proof") || n.includes("first")) return <KDCheck size={size} animate={animate} />;
  if (n.includes("elite") || n.includes("room"))  return <KDShield size={size} color="#7C3AED" inner="E" />;
  if (n.includes("leaderboard") || n.includes("#1")) return <KDCrown size={size} animate={animate} />;
  if (n.includes("level"))                         return <KDBolt size={size} animate={animate} />;
  if (n.includes("consist"))                       return <KDStar size={size} animate={animate} />;
  return <KDStar size={size} animate={animate} />;
}

// ── KD Empty state illustration ────────────────────────────────────────────────
function KDEmptyState({ type = "default", title, body, action }) {
  const { T } = useTheme();
  const icons = {
    chat:          <KDMascot state="encouraging" size={64} />,
    notifications: <KDBell size={56} />,
    rooms:         <KDMascot state="focused" size={64} />,
    leaderboard:   <KDTrophy size={56} gold />,
    default:       <KDMascot state="happy" size={64} />,
  };
  return (
    <div style={{ padding:"52px 24px", textAlign:"center" }}>
      <div style={{ display:"inline-block", marginBottom:16 }}>{icons[type] || icons.default}</div>
      {title && <div style={{ fontWeight:700, fontSize:17, color:T.text, marginBottom:8 }}>{title}</div>}
      {body  && <div style={{ fontSize:13, color:T.textMuted, lineHeight:1.6, maxWidth:260, margin:"0 auto 20px" }}>{body}</div>}
      {action}
    </div>
  );
}

