// ── Static data ────────────────────────────────────────────────────────────────
// Rooms are fully real-data — loaded from Firestore on mount
// ROOMS_INIT, GOAL_CATALOGUE, LEADERBOARD, FEED_INIT, AI_QUESTIONS, BADGES
// moved to src/constants/sampleData.js and src/constants/roomOptions.js

// Leaderboard built from Firestore users array (passed in from KickdayApp state)
function buildLeaderboard(me, allUsers = []) {
  const board = allUsers.map(u => ({
    init:      (u.userId || "?").slice(0, 2).toUpperCase(),
    name:      u.displayName || u.userId || "—",
    userId:    u.userId,
    username:  u.userId,
    photo:     u.photo || null,
    bannerUrl: u.bannerUrl || null,
    streak:    u.streak  ?? 0,
    proofs:    0,
    score:     0,
    xp:        u.xp      ?? 0,
    level:     u.level   ?? 1,
    color: "#" + (((u.userId?.charCodeAt(0) ?? 65) * 4567 + 1234) % 0xFFFFFF).toString(16).padStart(6, "0"),
    createdAt: u.joinedDate || "—",
    isMe:      me && u.userId === me.userId,
    badges:    u.badges  || [],
  }));
  return board.map(m => m.isMe && me
    ? { ...m, name: me.name, photo: me.photo || m.photo, bannerUrl: me.bannerUrl || m.bannerUrl, streak: me.streak, proofs: me.proofs, score: me.score, xp: me.xp, level: me.level }
    : m
  ).sort((a, b) => (b.xp ?? 0) - (a.xp ?? 0));
}

// ══════════════════════════════════════════════════════════════════════════════
// ── ENGINE 1: AUTO-MATCH SYSTEM ───────────────────────────────────────────────
// Takes goalKey + current rooms list.
// Returns { room, isNew, rooms } — the assigned room and the updated rooms list.
// ══════════════════════════════════════════════════════════════════════════════
function autoMatchRoom(goalKey, currentRooms, userInit = "AL") {
  const template = GOAL_CATALOGUE.find(g => g.key === goalKey);
  if (!template) return null;

  // Find an existing open room for this goal (not full, user not already in it)
  const existing = currentRooms.find(r =>
    r.goalKey === goalKey &&
    r.membersList &&
    r.membersList.length < r.max &&
    !r.membersList.includes(userInit)
  );

  if (existing) {
    // Slot user into existing room
    const updated = currentRooms.map(r =>
      r.id === existing.id
        ? { ...r, members: r.members + 1, membersList: [...r.membersList, userInit] }
        : r
    );
    return { room: updated.find(r => r.id === existing.id), isNew: false, rooms: updated };
  }

  // No room available — create a fresh one automatically
  const newRoom = {
    id: Date.now(),
    icon: template.icon,
    name: `${template.label} #${Math.floor(Math.random() * 900) + 100}`,
    goal: template.goal,
    goalKey: template.key,
    days: template.days,
    startDay: 0,
    members: 1,
    max: template.max,
    elite: false,
    tags: [],
    membersList: [userInit],
    startDate: new Date().toISOString().split("T")[0],
  };
  const updated = [...currentRooms, newRoom];
  return { room: newRoom, isNew: true, rooms: updated };
}

// ══════════════════════════════════════════════════════════════════════════════
// ── ENGINE 2: STREAK + KICK ENGINE ────────────────────────────────────────────
// userState shape: { streak, lastSubmitDate, missedDays, kickedFromRoom }
// Call runDailyStreakCheck() once per day (simulated on load in the hook below).
// ══════════════════════════════════════════════════════════════════════════════
// ── Consistency + streak helpers (used by profile/stats) ─────────────────────
function calcConsistencyScore(proofHistory, joinedRoomsCount = 1) {
  if (!joinedRoomsCount) return 0;
  const completedRooms = Math.max(0, joinedRoomsCount - 1);
  return Math.round((completedRooms / joinedRoomsCount) * 100);
}

function isNearMiss(proofHistory) {
  const today = todayStr ? todayStr() : new Date().toISOString().slice(0, 10);
  const latest = (proofHistory || []).filter(p => p.date === today).slice(-1)[0];
  if (!latest) return false;
  return Date.now() - new Date(latest.timestamp).getTime() < 3600000;
}

function isStreakAtRisk() {
  const now = new Date();
  const midnight = new Date(now);
  midnight.setHours(24, 0, 0, 0);
  return (midnight - now) < 7200000; // < 2 hours to midnight
}

function isGoodReminderTime() {
  const h = new Date().getHours();
  return h >= 8 && h <= 22;
}








function runDailyStreakCheck(userState) {
  const today = todayStr();
  // FIX: check both field names, use isSameUTCDay for robust comparison
  const lastDate = userState.lastSubmissionDate || userState.lastSubmitDate;
  if (lastDate && isSameUTCDay(lastDate, today)) return { ...userState, checkedToday: true };

  if (!lastDate) return userState;

  // ── Grace bypass: if grace is active, skip failure penalty entirely ──────────
  if (userState.graceActive) {
    const gStart = userState.graceStartDate;
    const gDays  = userState.graceDaysTotal || 1;
    if (gStart) {
      const elapsed = daysBetween(gStart, today);
      if (elapsed < gDays) {
        const xpPenalty = Math.max(0, (userState.xp ?? 0) - 5);
        return { ...userState, xp: xpPenalty, checkedToday: true };
      }
    }
    userState = { ...userState, graceActive: false, graceStartDate: null, graceDaysTotal: 0 };
  }

  const gap = daysBetween(lastDate, today);
  if (gap <= 1) return userState;

  const newMissed = Math.min((userState.missedDays ?? 0) + Math.min(gap - 1, 3), 3);
  return {
    ...userState,
    missedDays: newMissed,
    streak: newMissed >= 3 ? 0 : userState.streak,
    // FIX: clear lastSubmissionDate on full reset so next submit starts fresh
    lastSubmitDate:     newMissed >= 3 ? null : lastDate,
    lastSubmissionDate: newMissed >= 3 ? null : lastDate,
    kickedFromRoom: newMissed >= 3,
    warned: newMissed >= 2,
    kickStatus: newMissed >= 3 ? "kicked" : newMissed >= 2 ? "warned" : newMissed >= 1 ? "flagged" : "ok",
  };
}

function applyProofToStreak(userState) {
  const today = todayStr();
  // FIX: check both field names, use isSameUTCDay
  const lastDate = userState.lastSubmissionDate || userState.lastSubmitDate;
  if (lastDate && isSameUTCDay(lastDate, today)) return { ...userState, alreadySubmittedToday: true };

  // FIX: gap===1 means yesterday → streak continues; any other gap → reset to 1
  const gap = lastDate ? daysBetween(lastDate, today) : 1;
  const consecutive = gap === 1;
  return {
    ...userState,
    streak: consecutive ? userState.streak + 1 : 1,
    lastSubmitDate:     today,   // keep for backward compat
    lastSubmissionDate: today,   // FIX: canonical field
    missedDays: 0,
    warned: false,
    kickedFromRoom: false,
    kickStatus: "ok",
    alreadySubmittedToday: false,
    checkedToday: true,
  };
}

// ══════════════════════════════════════════════════════════════════════════════
// ── REAL-TIME ROOM DAY + STREAK HOOKS ─────────────────────────────────────────
// useRoomDay: re-renders at exactly local midnight so Day counter auto-ticks.
// useStreak:  same, but also fires a "missed day" check at midnight.
// ══════════════════════════════════════════════════════════════════════════════

// Hook: returns the live room day number, re-renders at midnight automatically.
function useRoomDay(room) {
  const [day, setDay] = useState(() => getRoomDayNumber(room));
  useEffect(() => {
    if (!room) return;
    setDay(getRoomDayNumber(room)); // sync immediately on mount/room change
    let timer;
    function scheduleNext() {
      const ms = getMsUntilMidnight();
      timer = setTimeout(() => {
        setDay(getRoomDayNumber(room));
        scheduleNext(); // re-schedule for the following day
      }, ms + 50); // +50ms buffer past midnight
    }
    scheduleNext();
    return () => clearTimeout(timer);
  }, [room?.id, room?.createdAt]);
  return day;
}

// Hook: returns live streak count and fires a check at midnight.
// streakData = { streak, lastSubmissionDate, lastSubmitDate }
function useStreakLive(streakValue) {
  const [displayed, setDisplayed] = useState(streakValue ?? 0);
  // Animate from old value to new value with smooth number scroll
  const prevRef = useRef(streakValue ?? 0);
  useEffect(() => {
    const target = streakValue ?? 0;
    if (target === prevRef.current) return;
    prevRef.current = target;
    setDisplayed(target);
  }, [streakValue]);
  return displayed;
}

// ── Animated number: smoothly counts from prev to next value ─────────────────
function AnimatedNumber({ value, duration = 600, style = {} }) {
  const [displayed, setDisplayed] = useState(value);
  const rafRef = useRef(null);
  const startRef = useRef({ from: value, to: value, t: 0 });

  useEffect(() => {
    const from = displayed;
    const to = value;
    if (from === to) return;
    const start = performance.now();
    startRef.current = { from, to, t: start };
    function tick(now) {
      const elapsed = now - start;
      const progress = Math.min(elapsed / duration, 1);
      // ease-out cubic
      const ease = 1 - Math.pow(1 - progress, 3);
      const cur = Math.round(from + (to - from) * ease);
      setDisplayed(cur);
      if (progress < 1) rafRef.current = requestAnimationFrame(tick);
    }
    rafRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafRef.current);
  }, [value]);

  return <span style={style}>{displayed}</span>;
}

// ── Premium Streak Card ───────────────────────────────────────────────────────
function StreakCard({ streak = 0, submittedToday = false, joinedRoom = null, style = {} }) {
  const { T } = useTheme();
  const liveDay = useRoomDay(joinedRoom);
  const [tick, setTick] = useState(0); // forces re-render at midnight

  // Schedule a re-render at midnight for the day-counter
  useEffect(() => {
    let timer;
    function scheduleNext() {
      const ms = getMsUntilMidnight();
      timer = setTimeout(() => {
        setTick(t => t + 1);
        scheduleNext();
      }, ms + 50);
    }
    scheduleNext();
    return () => clearTimeout(timer);
  }, []);

  const isActive  = streak > 0 && submittedToday;
  const isWarning = streak > 0 && !submittedToday;
  const isEmpty   = streak === 0;

  const accentColor = isActive  ? "#f97316"   // fire orange
                    : isWarning ? SHARED.yellow
                    : T.textFaint;

  const bgGradient  = isActive  ? (T.isDark ? "rgba(251,146,60,0.15)" : "linear-gradient(135deg, #fff7ed, #ffedd5)")
                    : isWarning ? (T.isDark ? "rgba(245,200,0,0.1)" : "linear-gradient(135deg, #fefce8, #fef9c3)")
                    : T.surface;

  const borderColor = isActive  ? T.warnBorder
                    : isWarning ? "#fde68a"
                    : T.border;

  return (
    <div style={{
      background:   bgGradient,
      border:       `1.5px solid ${borderColor}`,
      borderRadius: 16,
      padding:      "18px 20px",
      display:      "flex",
      alignItems:   "center",
      gap:          16,
      position:     "relative",
      overflow:     "hidden",
      transition:   "border-color 0.4s, background 0.4s",
      ...style,
    }}>
      <style>{`
        @keyframes flamePulse {
          0%, 100% { transform: scale(1) rotate(-2deg); }
          50%       { transform: scale(1.15) rotate(2deg); }
        }
        @keyframes streakCountIn {
          from { opacity: 0; transform: translateY(6px) scale(0.9); }
          to   { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes pulseRing {
          0%   { transform: scale(1);   opacity: 0.6; }
          100% { transform: scale(1.8); opacity: 0; }
        }
      `}</style>

      {/* Flame icon */}
      <div style={{ position: "relative", flexShrink: 0 }}>
        {isActive && (
          <div style={{
            position: "absolute", inset: 0, borderRadius: "50%",
            background: "#f9731622",
            animation: "pulseRing 1.6s ease-out infinite",
          }} />
        )}
        <div style={{
          width: 52, height: 52, borderRadius: 14,
          background: isEmpty ? T.surfaceAlt : isActive ? T.warnBg : T.infoBg,
          border: `1px solid ${borderColor}`,
          display: "flex", alignItems: "center", justifyContent: "center",
          fontSize: 26,
          animation: isActive ? "flamePulse 2s ease-in-out infinite" : "none",
        }}>
          {isEmpty ? <KDMascot state="disappointed" size={20} animate={false}/> : isWarning ? <KDShield size={20} color="#F59E0B" inner="!"/> : <KDFlame size={20}/>}
        </div>
      </div>

      {/* Main content */}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          display: "flex", alignItems: "baseline", gap: 6, marginBottom: 2,
          animation: "streakCountIn 0.4s ease",
        }}>
          <AnimatedNumber
            value={streak}
            style={{ fontWeight: 800, fontSize: 32, color: accentColor, lineHeight: 1, fontVariantNumeric: "tabular-nums" }}
          />
          <span style={{ fontWeight: 700, fontSize: 16, color: accentColor, lineHeight: 1 }}>
            {streak === 1 ? "Day Streak" : "Day Streak"}
          </span>
        </div>
        <div style={{ fontSize: 12, color: T.textMuted, lineHeight: 1.4 }}>
          {isEmpty       ? "Submit a proof to start your streak"           :
           submittedToday ? <span style={{display:"inline-flex",alignItems:"center",gap:4}}><KDCheck size={14}/>Streak locked in for today</span> : <span style={{display:"inline-flex",alignItems:"center",gap:4}}><KDBolt size={14}/>Post proof before midnight</span>}
        </div>
      </div>

      {/* Right — room day badge */}
      {joinedRoom && (
        <div style={{
          flexShrink: 0, textAlign: "center",
          padding: "8px 12px",
          background: T.surfaceAlt,
          border: `1px solid ${T.border}`,
          borderRadius: 10,
        }}>
          <div style={{ fontSize: 10, fontWeight: 600, color: T.textMuted, textTransform: "uppercase", letterSpacing: 0.6, marginBottom: 2 }}>Room Day</div>
          <AnimatedNumber
            value={liveDay}
            style={{ fontSize: 22, fontWeight: 800, color: T.text, lineHeight: 1, display: "block" }}
          />
        </div>
      )}
    </div>
  );
}









// ══════════════════════════════════════════════════════════════════════════════
// ── HALL OF SHAME + LOWEST XP BADGE SYSTEM ───────────────────────────────────
// Eligibility: level >= 2 AND league in [Bronze, Silver, Gold, Elite]
// ══════════════════════════════════════════════════════════════════════════════

// ELIGIBLE_LEAGUES, LOWEST_XP_BADGE_DURATION_DAYS moved to src/constants/gameConfig.js

// ── RECOVERY ZONE SYSTEM (replaces Hall of Shame) ────────────────────────────
// Shows users who lost streaks or dropped rank — neutral framing, no shame.
// Goal: turn failure into motivation via Comeback Missions.
// COMEBACK_MISSIONS moved to src/constants/gameConfig.js

function isRecoveryEligible(user) {
  const level = user.level ?? calcLevel(user.xp ?? 0);
  const league = user.league ?? calcLeague(user.xp ?? 0);
  return level >= 2 && ELIGIBLE_LEAGUES.includes(league);
}

function buildRecoveryZone(users) {
  const eligible = users.filter(isRecoveryEligible);
  // Sort ascending by XP — lowest first (these are users who need a comeback)
  const sorted = [...eligible].sort((a, b) => {
    const xpDiff = (a.xp ?? 0) - (b.xp ?? 0);
    if (xpDiff !== 0) return xpDiff;
    return (a.streak ?? 0) - (b.streak ?? 0);
  });
  const top10 = sorted.slice(0, 10);
  const now = new Date().toISOString();
  return top10.map((u, i) => ({
    ...u,
    recoveryRank: i + 1,
    lastUpdated: now,
  }));
}

function assignRecoveryBadge(users) {
  const eligible = users.filter(isRecoveryEligible);
  if (eligible.length === 0) return users;
  const lowestXP = Math.min(...eligible.map(u => u.xp ?? 0));
  const lowestUser = eligible.find(u => (u.xp ?? 0) === lowestXP);
  const now = Date.now();
  const expiresAt = now + LOWEST_XP_BADGE_DURATION_DAYS * 86400000;
  return users.map(u => {
    const badges = (u.badges || []).filter(b => b.id !== "lowest_xp" || new Date(b.expiresAt).getTime() > now);
    if (lowestUser && u.userId === lowestUser.userId) {
      const already = badges.find(b => b.id === "lowest_xp");
      if (!already) badges.push({ id: "lowest_xp", icon: "chart", name: "Comeback Mode", expiresAt: new Date(expiresAt).toISOString() });
    }
    return { ...u, badges };
  });
}

async function runDailyShameUpdate(users) {
  const withBadges = assignRecoveryBadge(users);
  const recovery = buildRecoveryZone(withBadges);
  return { updatedUsers: withBadges, hallOfShame: recovery };
}

function useHallOfShame(leaderboard) {
  const [recovery, setRecovery] = useState([]);
  useEffect(() => {
    const eligible = leaderboard.filter(isRecoveryEligible);
    const sorted = [...eligible].sort((a, b) => {
      const xpDiff = (a.xp ?? 0) - (b.xp ?? 0);
      if (xpDiff !== 0) return xpDiff;
      return (a.streak ?? 0) - (b.streak ?? 0);
    });
    setRecovery(sorted.slice(0, 10).map((u, i) => ({ ...u, recoveryRank: i + 1, hallOfShameRank: i + 1 })));
  }, [leaderboard]);
  return recovery;
}

