// (full implementation below near proof engine)

// ── Smart reminder timing: fire at 8am, 12pm, 8pm local if not submitted ─────
function shouldFireReminder(submittedToday) {
  if (submittedToday) return false;
  const h = new Date().getHours();
  return h === 8 || h === 12 || h === 20;
}

// ── Onboarding constants defined below near proof engine ──────────────────────

// ── Peer voting ───────────────────────────────────────────────────────────────
function voteOnProof(proof, vote /* "valid" | "suspicious" */) {
  const votes = proof.votes || { valid: 0, suspicious: 0 };
  return { ...proof, votes: { ...votes, [vote]: votes[vote] + 1 } };
}

function flagProof(proof, reason) {
  const flags = proof.flags || [];
  return { ...proof, flags: [...flags, { reason, timestamp: new Date().toISOString() }] };
}

// ── Premium: unlocks elite rooms + advanced stats ─────────────────────────────
function canJoinEliteRoom(user) {
  return !!(user?.premium) || (user?.level ?? 1) >= 10;
}

// ── Instant rejoin after failure ──────────────────────────────────────────────
function resetForRejoin(userState) {
  return {
    ...userState,
    kickedFromRoom: false,
    kickStatus: "ok",
    missedDays: 0,
    warned: false,
    streak: 0,
  };
}

// ── Streak-at-risk alert banner ───────────────────────────────────────────────
// NOTE: this is a warning-only banner. There is intentionally no "quick submit"
// shortcut — proof submission always goes through the full proof flow (which
// validates the proof and runs it through the AI referee / safety checks).
function StreakAtRiskAlert({ submittedToday }) {
  const { T } = useTheme();
  const [show, setShow] = useState(false);
  useEffect(() => {
    // isStreakAtRisk defined below — safe because this only runs after mount
    const id = setInterval(() => setShow(!submittedToday && (() => { const now = new Date(); return (86400 - (now.getHours()*3600 + now.getMinutes()*60 + now.getSeconds())) < 7200; })()), 60000);
    setShow(!submittedToday && (() => { const now = new Date(); return (86400 - (now.getHours()*3600 + now.getMinutes()*60 + now.getSeconds())) < 7200; })());
    return () => clearInterval(id);
  }, [submittedToday]);
  if (!show) return null;
  return (
    <div style={{ background: T.warnBg, border: `1.5px solid ${T.warnBorder}`, borderRadius: 9, padding: "10px 16px", marginBottom: 12, display: "flex", alignItems: "center", gap: 10, fontSize: 13, color: T.warnText }}>
      <span></span>
      <span style={{ flex: 1 }}><strong>Streak at risk!</strong> Less than 2 hours left today. Submit your proof from the dashboard to keep your streak.</span>
    </div>
  );
}

