// ── Social graph hook ─────────────────────────────────────────────────────────
function useSocialGraph(initialFollowing = []) {
  const [following, setFollowing] = useState(initialFollowing);
  const toggle = useCallback((userId) => {
    setFollowing(prev => prev.includes(userId) ? prev.filter(x => x !== userId) : [...prev, userId]);
  }, []);
  const isFollowing = (userId) => following.includes(userId);
  return { following, toggle, isFollowing };
}

// ── Onboarding first-proof timer display ─────────────────────────────────────
function OnboardingProofTimer({ onboardingComplete, submittedToday, onExpire }) {
  const { T } = useTheme();
  const [timeLeft, setTimeLeft] = useState(600000);
  useEffect(() => {
    if (onboardingComplete || submittedToday) return;
    const start = Date.now();
    const id = setInterval(() => {
      const left = Math.max(0, 600000 - (Date.now() - start));
      setTimeLeft(left);
      if (left === 0) { clearInterval(id); onExpire?.(); }
    }, 1000);
    return () => clearInterval(id);
  }, [onboardingComplete, submittedToday]);
  // Hide once proof submitted OR onboarding already complete
  if (onboardingComplete || submittedToday) return null;
  const mins = Math.floor(timeLeft / 60000);
  const secs = Math.floor((timeLeft % 60000) / 1000);
  return (
    <div style={{ background: T.infoBg, border: `1px solid ${T.infoBorder}`, borderRadius: 9, padding: "8px 14px", marginBottom: 10, fontSize: 12, color: T.infoText, display: "flex", alignItems: "center", gap: 8 }}>
      <span style={{display:"inline-flex"}}><KDBolt size={14} color="#7C3AED"/></span>
      <span>Submit your first proof within <strong>{mins}:{secs.toString().padStart(2,"0")}</strong> for <strong>+25 XP bonus!</strong></span>
    </div>
  );
}

// EntryFeeGate — full implementation below near proof engine
function useDailyReminder({ submittedToday, userState, showToast, notifPrefs }) {
  const firedRef = useRef(false);
  useEffect(() => {
    if (submittedToday || firedRef.current) return;
    if (!notifPrefs?.["Proof submission reminders"]) return;
    const id = setInterval(() => {
      if (submittedToday || firedRef.current) { clearInterval(id); return; }
      if (!isGoodReminderTime()) return;
      const atRisk = isStreakAtRisk();
      if (atRisk && (userState.streak ?? 0) > 0) {
        firedRef.current = true;
        clearInterval(id);
        showToast(`Streak at risk! < 2h to submit today's proof.`, "error");
        if ("Notification" in window && Notification.permission === "granted") {
          new Notification("Kickday — Streak at risk!", {
            body: `You have less than 2 hours to submit today's proof.`,
            icon: "data:image/webp;base64,",
          });
        }
      }
    }, 60000);
    return () => clearInterval(id);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [submittedToday, userState.streak]);
}


