// ── SessionVoteModal — post-session satisfaction vote ─────────────────────────
// Shown to the participant after leaving/completing a room session.
// Logic: majority (>50%) "no" + at least 2 no votes → XP penalty on responsible user.
// One vote per participant; duplicate votes silently ignored by fbCastSessionVote.
function SessionVoteModal({ open, sessionId, roomName, voterUid, responsibleUid, onClose, onVoted, showToast }) {
  const { T } = useTheme();
  const [voted,   setVoted]   = useState(false);
  const [loading, setLoading] = useState(false);

  // Reset when a new session vote is triggered
  useEffect(() => { if (open) { setVoted(false); setLoading(false); } }, [open, sessionId]);

  if (!open || !sessionId) return null;

  async function castVote(vote /* "yes" | "no" */) {
    if (loading || voted || !voterUid || !sessionId) return;
    setLoading(true);
    const result = await fbCastSessionVote(sessionId, voterUid, vote).catch(() => ({ ok: false, error: "Network error" }));
    setLoading(false);
    if (!result.ok && result.error === "Already voted") {
      setVoted(true);
      onVoted?.();
      onClose?.();
      return;
    }
    if (!result.ok) { showToast?.("Vote failed. Try again.", "error"); return; }
    setVoted(true);

    // Evaluate after a short delay so other in-flight votes settle
    setTimeout(async () => {
      const eval_ = await fbEvaluateSessionVotes(sessionId, responsibleUid).catch(() => null);
      if (eval_?.penaltyFired) {
        // Only notify the responsible user — no global broadcast to prevent shaming
        if (voterUid === responsibleUid) {
          showToast?.(`Session rated unsatisfactory. -${SESSION_VOTE_XP_PENALTY} XP applied.`, "error");
        }
      }
      onVoted?.();
    }, 1500);
    onClose?.();
  }

  return (
    <Modal open={open} onClose={onClose} width={380} title="Rate your session">
      <div style={{ textAlign:"center", padding:"8px 0 12px" }}>
        <div style={{display:"flex",justifyContent:"center",marginBottom:10}}><KDMascot state="focused" size={48} animate={false}/></div>
        <div style={{ fontWeight:600, fontSize:15, color:T.text, marginBottom:6 }}>
          Was your session in <strong>"{roomName}"</strong> satisfactory?
        </div>
        <div style={{ fontSize:12, color:T.textMuted, marginBottom:22, lineHeight:1.6 }}>
          Your vote is anonymous. Majority "No" votes trigger an accountability review.
        </div>
        <div style={{ display:"flex", gap:10, justifyContent:"center" }}>
          <button
            onClick={() => castVote("yes")}
            disabled={loading || voted}
            style={{ flex:1, background:T.successBg, border:`1.5px solid ${T.successBorder}`, color:T.successText, borderRadius:10, padding:"11px 0", fontWeight:700, fontSize:14, cursor:loading||voted?"not-allowed":"pointer", fontFamily:"inherit", opacity:loading||voted?0.6:1 }}
          >
            <svg width={13} height={13} viewBox="0 0 24 24" fill="none"><path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3H14z" fill="currentColor"/></svg> Yes
          </button>
          <button
            onClick={() => castVote("no")}
            disabled={loading || voted}
            style={{ flex:1, background:T.errorBg, border:`1.5px solid #fecaca`, color:T.errorText, borderRadius:10, padding:"11px 0", fontWeight:700, fontSize:14, cursor:loading||voted?"not-allowed":"pointer", fontFamily:"inherit", opacity:loading||voted?0.6:1 }}
          >
            <svg width={13} height={13} viewBox="0 0 24 24" fill="none"><path d="M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2 2 0 0 0 2 2.3H10z" fill="currentColor"/></svg> No
          </button>
        </div>
        {voted && <div style={{ marginTop:14, fontSize:12, color:T.textMuted }}>Vote recorded. Thanks!</div>}
        <Btn variant="ghost" style={{ marginTop:12, width:"100%" }} onClick={onClose}>Skip</Btn>
      </div>
    </Modal>
  );
}

// Visual config for each league — used everywhere a badge is rendered
const LEAGUE_STYLE_BASE = {
  bronze: { bg: "#fdf3e7", bgDark: "#2a1800", color: "#92400e", colorDark: "#fbbf24", border: "#d97706", dot: "#b45309" },
  silver: { bg: "#f3f4f6", bgDark: "#1f2937", color: "#4b5563", colorDark: "#9ca3af", border: "#9ca3af", dot: "#6b7280" },
  gold:   { bg: "#fefce8", bgDark: "rgba(245,200,0,0.12)", color: "#854d0e", colorDark: "#F5C800", border: "#F5C800", dot: "#ca8a04" },
  platinum: { bg: "#e2e8f0", bgDark: "#1e293b", color: "#475569", colorDark: "#94a3b8", border: "#94a3b8", dot: "#64748b" },
  diamond: { bg: "#e0f2fe", bgDark: "#082f49", color: "#0369a1", colorDark: "#38bdf8", border: "#0ea5e9", dot: "#0284c7" },
};

function LeagueBadge({ xp, size = "sm" }) {
  const { T } = useTheme();
  const league = calcLeague(xp ?? 0);
  const base = LEAGUE_STYLE_BASE[league] || LEAGUE_STYLE_BASE.bronze;
  const s = {
    bg: T.isDark ? base.bgDark : base.bg,
    color: T.isDark ? base.colorDark : base.color,
    border: base.border, dot: base.dot,
  };
  const pad = size === "xs" ? "1px 6px" : "2px 9px";
  const fs  = size === "xs" ? 9 : 11;
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 4,
      background: s.bg, color: s.color,
      border: `1px solid ${s.border}`,
      borderRadius: 100, padding: pad,
      fontSize: fs, fontWeight: 700,
      whiteSpace: "nowrap", flexShrink: 0,
    }}>
      <span style={{ width: fs - 2, height: fs - 2, borderRadius: "50%", background: s.dot, display: "inline-block", flexShrink: 0 }} />
      {league}
    </span>
  );
}

function xpToNextLevel(xp) {
  const nextLevelXP = xpForLevel(calcLevel(xp) + 1);  // xp needed for next level
  return nextLevelXP - xp;                            // how many xp still needed
}

// xpProgressPct imported from api.jsx

// ══════════════════════════════════════════════════════════════════════════════
// ── ENGINE 3: DAILY PROOF SYSTEM ──────────────────────────────────────────────
// Builds a proof record and a feed entry. Call on successful AI moderation pass.
// ══════════════════════════════════════════════════════════════════════════════
function buildProofRecord({ file, preview, link, text, userInit, userName, userColor, joinedRoom, streak = 0 }) {
  const today = todayStr();
  const now = new Date();
  const timeStr = now.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", hour12: true });
  const tsISO = now.toISOString();
  const entryId = Date.now();

  // Canonical proof record stored in proofHistory + room.media
  const record = {
    id: `proof_${userInit}_${today}_${entryId}`,
    userId: userInit,
    username: userName,
    userColor,
    date: today,
    dateKey: today,                  // YYYY-MM-DD — used for one-per-day dedup check
    timestamp: tsISO,
    timeStr,
    image: preview || null,          // base64 data URL — works in sandboxed iframes
    link: link || null,
    note: text || null,
    roomId: joinedRoom?.id != null ? String(joinedRoom.id) : null,
    roomName: joinedRoom?.name || null,
    streak,
    verified: true,
  };

  const feedEntry = {
    id: `proof_${userInit}_${today}_${entryId}`,
    user: userName,
    init: userInit,
    color: userColor,
    time: tsISO,
    createdAt: tsISO,
    type: "proof",
    verified: true,
    text: text || (link ? "Shared a proof link" : "Submitted today's proof."),
    imageUrl: preview || null,
    proofLink: link || null,
    caption: ` Proof — ${joinedRoom?.name || "Your room"} · Day ${joinedRoom?.startDay || 1}`,
    date: today,
    streak,
    roomId: joinedRoom?.id != null ? String(joinedRoom.id) : null,  // ← room isolation tag (always string)
  };

  return { record, feedEntry };
}

// ══════════════════════════════════════════════════════════════════════════════
// ── Auto-match modal: goal picker → interview → room assignment ────────────────
// ══════════════════════════════════════════════════════════════════════════════
function AutoMatchModal({ open, onClose, rooms, onMatched }) {
  const { T } = useTheme();
  const [phase, setPhase] = useState("idle"); // idle | matching | found
  const [progress, setProgress] = useState(0);
  const [matchedRoom, setMatchedRoom] = useState(null);
  const [dots, setDots] = useState(0);

  useEffect(() => {
    if (!open) { setPhase("idle"); setProgress(0); setMatchedRoom(null); }
    else { setPhase("matching"); }
  }, [open]);

  useEffect(() => {
    if (phase !== "matching") return;
    let p = 0;
    const interval = setInterval(() => {
      p += Math.random() * 15 + 5;
      if (p >= 100) {
        p = 100;
        clearInterval(interval);
        // Automatch logic: pick best available room
        const available = rooms.filter(r => (r.members ?? 0) < (r.max ?? 8));
        const best = available.length > 0
          ? available[Math.floor(Math.random() * Math.min(3, available.length))]
          : rooms[0] || null;
        setMatchedRoom(best);
        setPhase("found");
        setTimeout(() => { if (best) onMatched(best); }, 1200);
      }
      setProgress(p);
    }, 100);
    return () => clearInterval(interval);
  }, [phase]);

  useEffect(() => {
    if (phase !== "matching") return;
    const id = setInterval(() => setDots(d => (d + 1) % 4), 350);
    return () => clearInterval(id);
  }, [phase]);

  if (!open) return null;

  const STEPS = [
    { pct: 0,  label: "Scanning active rooms…" },
    { pct: 30, label: "Checking timezone…" },
    { pct: 55, label: "Matching streak level…" },
    { pct: 75, label: "Verifying activity…" },
    { pct: 90, label: "Securing your slot…" },
  ];
  const step = STEPS.filter(s => progress >= s.pct).slice(-1)[0] || STEPS[0];

  return (
    <Modal open={open} onClose={onClose} width={400} title="">
      <div style={{ padding: "8px 0" }}>
        {phase === "matching" && (
          <>
            <div style={{ textAlign: "center", marginBottom: 24 }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: SHARED.yellow, letterSpacing: 2, textTransform: "uppercase", marginBottom: 6 }}>AUTO MATCH</div>
              <div style={{ fontWeight: 800, fontSize: 20, color: T.text, letterSpacing: -0.5 }}>
                Finding your room{".".repeat(dots)}
              </div>
              <div style={{ fontSize: 12, color: T.textMuted, marginTop: 6 }}>
                Matched by activity · streak · timezone
              </div>
            </div>
            <div style={{ marginBottom: 20 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: T.textMuted, marginBottom: 6 }}>
                <span>{step.label}</span>
                <span style={{ fontFamily: "monospace", color: SHARED.yellow }}>{Math.round(progress)}%</span>
              </div>
              <div style={{ height: 4, borderRadius: 99, background: T.border, overflow: "hidden" }}>
                <div style={{ height: "100%", borderRadius: 99, background: SHARED.yellow, width: `${progress}%`, transition: "width 0.12s ease" }} />
              </div>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {[
                { l: "Activity level", v: "High" },
                { l: "Timezone", v: Intl.DateTimeFormat().resolvedOptions().timeZone.split("/").pop().replace(/_/g, " ") },
                { l: "Focus compatibility", v: "Strong" },
              ].map((item, i) => (
                <div key={item.l} style={{ display: "flex", gap: 12, alignItems: "center", opacity: progress > i * 30 ? 1 : 0.3, transition: "opacity 0.3s" }}>
                  <div style={{ width: 6, height: 6, borderRadius: "50%", background: progress > (i + 1) * 30 ? SHARED.yellow : T.border, flexShrink: 0 }} />
                  <span style={{ fontSize: 12, color: T.textMuted, flex: 1 }}>{item.l}</span>
                  <span style={{ fontSize: 12, fontWeight: 600, color: T.text }}>{item.v}</span>
                </div>
              ))}
            </div>
          </>
        )}
        {phase === "found" && matchedRoom && (
          <div style={{ textAlign: "center" }}>
            <div style={{display:"flex",justifyContent:"center",marginBottom:12}}><KDCheck size={52} animate={true}/></div>            <div style={{ fontWeight: 800, fontSize: 18, color: T.text, marginBottom: 4 }}>Room found!</div>
            <div style={{ background: T.surfaceAlt, border: `1px solid ${SHARED.yellow}44`, borderRadius: 12, padding: "14px", marginTop: 16 }}>
              <div style={{display:"inline-flex",justifyContent:"center",marginBottom:6}}><KDGoalIcon goalKey={matchedRoom?.goalKey||""} size={28}/></div>
              <div style={{ fontWeight: 700, fontSize: 15, color: T.text }}>{matchedRoom.name}</div>
              <div style={{ fontSize: 12, color: T.textMuted }}>{matchedRoom.goal}</div>
            </div>
            <div style={{ fontSize: 12, color: T.textMuted, marginTop: 12 }}>Joining automatically…</div>
          </div>
        )}
        {phase === "found" && !matchedRoom && (
          <div style={{ textAlign: "center", padding: "20px 0" }}>
            <div style={{display:"flex",justifyContent:"center",marginBottom:10}}><KDMascot state="disappointed" size={40} animate={false}/></div>
            <div style={{ fontWeight: 600, fontSize: 16, color: T.text, marginBottom: 6 }}>No rooms available</div>
            <div style={{ fontSize: 13, color: T.textMuted, marginBottom: 16 }}>All rooms are full. Try again later.</div>
            <Btn onClick={onClose}>Close</Btn>
          </div>
        )}
      </div>
    </Modal>
  );
}

function StreakStatusBanner({ userState, onSubmit, onGrace, submittedToday }) {
  const { T } = useTheme();
  // Hide entirely if ok, or if user already submitted today (clears all warnings)
  if (!userState.kickedFromRoom && userState.kickStatus === "ok") return null;
  if (submittedToday && userState.kickStatus !== "kicked") return null;

  const configs = {
    kicked:  { bg: T.errorBg, border: T.errorBorder, text: T.errorText, icon: "skull", msg: "You were auto-kicked for missing 3 days. Leave the room to re-apply." },
    warned:  { bg: T.warnBg, border: T.warnBorder, text: T.warnText, icon: "warn", msg: `Warning: ${userState.missedDays} days missed. Miss one more and you're out.` },
    flagged: { bg: T.infoBg, border: T.infoBorder, text: T.infoText, icon: "bell", msg: "You missed yesterday. Submit today's proof to keep your streak." },
  };
  const c = configs[userState.kickStatus] || configs.flagged;
  return (
    <div style={{ background: c.bg, border: `1px solid ${c.border}`, borderRadius: 9, padding: "10px 16px", marginBottom: 16, display: "flex", alignItems: "center", gap: 10, fontSize: 13, color: c.text }}>
      <KDIconByKey keyName={c.icon} size={22} />
      <span style={{ flex: 1 }}>{c.msg}</span>
      {userState.kickStatus === "warned" && (
        <Btn size="sm" variant="ghost" onClick={onGrace}>Grace period</Btn>
      )}
    </div>
  );
}

