// ══════════════════════════════════════════════════════════════════════════════
// ── SYSTEM 4: COUNTDOWN TIMER ─────────────────────────────────────────────────
// Counts down to 23:59:59 every day. Fires onMissed when midnight passes
// and user hasn't submitted. Displayed on Dashboard and Activity sidebar.
// ══════════════════════════════════════════════════════════════════════════════
function useCountdown() {
  const [timeLeft, setTimeLeft] = useState({ h: 0, m: 0, s: 0, total: 0, tz: "" });

  useEffect(() => {
    const tz = getUserTimezone();
    function tick() {
      const now = new Date();
      // Use Intl to get the true local time in the user's timezone
      const parts = new Intl.DateTimeFormat("en-US", {
        timeZone: tz, hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false,
      }).formatToParts(now);
      const get = t => parseInt(parts.find(p => p.type === t)?.value || "0");
      const hh = get("hour") % 24; // normalise 24→0
      const mm = get("minute"); const ss = get("second");
      const elapsed = hh * 3600 + mm * 60 + ss;
      const totalSecs = Math.max(0, 86400 - elapsed - 1);
      setTimeLeft({ h: Math.floor(totalSecs / 3600), m: Math.floor((totalSecs % 3600) / 60), s: totalSecs % 60, total: totalSecs * 1000, tz });
    }
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  return timeLeft;
}

function CountdownTimer({ submitted, compact = false }) {
  const { T } = useTheme();
  const { h, m, s, total, tz } = useCountdown();
  const pct = total / 86400000; // fraction of day remaining
  const urgent = total < 3600000;   // < 1 hour
  const warning = total < 10800000; // < 3 hours

  const color = submitted ? SHARED.green
    : urgent  ? SHARED.red
    : warning ? "#f97316"
    : T.text;

  const bg = submitted ? T.successBg
    : urgent  ? T.errorBg
    : warning ? T.warnBg
    : T.surfaceAlt;

  const border = submitted ? T.successBorder
    : urgent  ? T.errorBorder
    : warning ? T.warnBorder
    : T.border;

  const pad = n => String(n).padStart(2, "0");
  const label = submitted ? "Submitted" : `${pad(h)}:${pad(m)}:${pad(s)}`;
  const sub = submitted ? "Streak safe" : urgent ? "Submit NOW or lose streak!" : warning ? "Running out of time" : "Until midnight deadline";

  if (compact) {
    return (
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 12px", background: bg, border: `1px solid ${border}`, borderRadius: 8 }}>
        <span style={{ fontSize: 13, fontWeight: 700, fontFamily: "monospace", color, letterSpacing: 1 }}>{label}</span>
        <span style={{ fontSize: 11, color: submitted ? SHARED.green : T.textFaint }}>{sub}</span>
      </div>
    );
  }

  return (
    <div style={{ background: bg, border: `1px solid ${border}`, borderRadius: 12, padding: "16px 20px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10 }}>
        <div>
          <div style={{ fontSize: 11, fontWeight: 500, color: T.textMuted, textTransform: "uppercase", letterSpacing: 0.7, marginBottom: 4 }}>
            {submitted ? "Today's status" : `Time remaining — ${tz?.split("/").pop()?.replace(/_/g," ") || "Local"}`}
          </div>
          <div style={{ fontSize: 32, fontWeight: 700, fontFamily: "monospace", color, letterSpacing: 2, lineHeight: 1 }}>
            {label}
          </div>
          <div style={{ fontSize: 12, color: submitted ? SHARED.green : urgent ? SHARED.red : T.textMuted, marginTop: 4 }}>{sub}</div>
        </div>
        {!submitted && (
          <div style={{ fontSize: 28 }}><span style={{width:12,height:12,borderRadius:"50%",background:urgent?"#EF4444":warning?"#EAB308":"#10B981",display:"inline-block"}}/></div>
        )}
      </div>
      {/* Progress bar - fills as day progresses */}
      {!submitted && (
        <div style={{ background: T.border, borderRadius: 4, height: 4, overflow: "hidden" }}>
          <div style={{ width: `${(1 - pct) * 100}%`, height: "100%", background: urgent ? SHARED.red : warning ? "#f97316" : SHARED.yellow, borderRadius: 4, transition: "width 1s linear" }} />
        </div>
      )}
    </div>
  );
}

