// ══════════════════════════════════════════════════════════════════════════════
// ── SAFETY GATE: required before chat / proof / room interactions ────────────
// ══════════════════════════════════════════════════════════════════════════════

function SafetyGate({ onAccept, displayName }) {
  const { T } = useTheme();
  const [scrolledToEnd, setScrolledToEnd] = useState(false);
  const [checked, setChecked] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  function handleScroll(e) {
    const el = e.currentTarget;
    if (el.scrollTop + el.clientHeight >= el.scrollHeight - 16) setScrolledToEnd(true);
  }

  async function handleAccept() {
    if (submitting) return;
    setSubmitting(true);
    try { await onAccept?.(); } finally { setSubmitting(false); }
  }

  const canContinue = scrolledToEnd && checked;

  return (
    <div style={{ minHeight: "100vh", background: T.bg, display: "flex", alignItems: "center", justifyContent: "center", padding: "24px 16px", fontFamily: APP_FONT }}>
      <style>{`@keyframes safetyIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}`}</style>
      <div style={{ width: "100%", maxWidth: 480, background: T.surface, border: `1px solid ${T.border}`, borderRadius: 18, padding: "26px 22px", display: "flex", flexDirection: "column", gap: 14, animation: "safetyIn 0.35s both" }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ width: 50, height: 50, borderRadius: 14, background: "#22c55e18", border: "1.5px solid #22c55e44", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 10px", fontSize: 24 }}>🛡️</div>
          <div style={{ fontWeight: 900, fontSize: 20, color: T.text, letterSpacing: -0.4 }}>
            {displayName ? `One last thing, ${displayName}` : "One last thing"}
          </div>
          <div style={{ fontSize: 13, color: T.textMuted, marginTop: 6, lineHeight: 1.55 }}>
            Before you can chat, submit proof, or interact in rooms, please read and accept our Community Safety Guidelines.
          </div>
        </div>

        <div onScroll={handleScroll} style={{ maxHeight: 240, overflowY: "auto", border: `1px solid ${T.border}`, borderRadius: 12, padding: "14px 16px", background: T.surfaceAlt }}>
          {COMMUNITY_GUIDELINES.map(([title, body]) => (
            <div key={title} style={{ marginBottom: 12 }}>
              <div style={{ fontWeight: 700, fontSize: 13, color: T.text, marginBottom: 3 }}>{title}</div>
              <div style={{ fontSize: 12, color: T.textMuted, lineHeight: 1.6 }}>{body}</div>
            </div>
          ))}
          <div style={{ fontSize: 11, color: T.textFaint, marginTop: 4, lineHeight: 1.6 }}>
            Strike 1: Warning. Strike 2: 24–72h suspension. Strike 3+: Permanent ban. Child safety violations skip directly to a permanent ban.
          </div>
        </div>

        {!scrolledToEnd && (
          <div style={{ fontSize: 11, color: "#F59E0B", textAlign: "center", fontWeight: 600 }}>↓ Scroll to the bottom to continue</div>
        )}

        <label style={{ display: "flex", gap: 10, alignItems: "flex-start", cursor: scrolledToEnd ? "pointer" : "default", opacity: scrolledToEnd ? 1 : 0.5 }}>
          <input type="checkbox" checked={checked} disabled={!scrolledToEnd} onChange={e => setChecked(e.target.checked)} style={{ marginTop: 2, width: 16, height: 16, accentColor: "#22c55e", flexShrink: 0 }} />
          <span style={{ fontSize: 12, color: T.textMuted, lineHeight: 1.5 }}>I have read and agree to follow the Kickday Community Safety Guidelines, Terms of Service, and Privacy Policy.</span>
        </label>

        <button onClick={handleAccept} disabled={!canContinue || submitting} style={{ width: "100%", padding: "13px", borderRadius: 11, border: "none", background: canContinue ? "#22c55e" : T.surfaceAlt, color: canContinue ? "#06210f" : T.textFaint, fontWeight: 800, fontSize: 14, cursor: canContinue ? "pointer" : "default", fontFamily: "inherit", transition: "background 0.15s" }}>
          {submitting ? "Saving…" : "I Agree & Continue"}
        </button>

        <DiscordCTA />
      </div>
    </div>
  );
}


// Shows each member's submission status, streak, and risk level.
// ══════════════════════════════════════════════════════════════════════════════

// Simulated member status data (in real app, this comes from backend)
// No fake member status data — only real user state is used
// MEMBER_STATUS_DATA moved to src/constants/sampleData.js

function getMemberStatus(missedDays, submittedToday, kicked) {
  if (kicked) return "kicked";
  if (missedDays >= 2) return "at_risk";
  if (missedDays >= 1 || !submittedToday) return "flagged";
  return "active";
}

function MemberStatusBadge({ status }) {
  const { T } = useTheme();
  const configs = {
    active:   { label: "Active",   bg: T.successBg,  color: T.successText,  border: T.successBorder },
    flagged:  { label: "Not yet",  bg: T.isDark ? "rgba(245,200,0,0.1)" : SHARED.yellowLight, color: T.isDark ? "#fbbf24" : "#92400e", border: SHARED.yellowBorder },
    at_risk:  { label: "At Risk",  bg: T.warnBg,     color: T.warnText,     border: T.warnBorder },
    kicked:   { label: "Kicked",   bg: T.errorBg,    color: T.errorText,    border: T.errorBorder },
  };
  const c = configs[status] || configs.flagged;
  return (
    <span style={{ fontSize: 10, fontWeight: 600, padding: "2px 8px", borderRadius: 100, background: c.bg, color: c.color, border: `1px solid ${c.border}`, whiteSpace: "nowrap" }}>
      {c.label}
    </span>
  );
}

// ── ReportUserModal — moderation report for a room member ────────────────────
// FIX 3: Correct reasons per spec; wired to fbAddReport for actual admin storage
// REPORT_REASONS moved to src/constants/safetyConfig.js
function ReportUserModal({ open, onClose, reportTarget, reporterUid, evidence = {} }) {
  const { T } = useTheme();
  const [reason, setReason] = useState("");
  const [detail, setDetail] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const [saving, setSaving] = useState(false);
  const [reportError, setReportError] = useState("");
  const submitLockRef = useRef(false);
  useEffect(() => { if (open) { setReason(""); setDetail(""); setSubmitted(false); setSaving(false); setReportError(""); submitLockRef.current = false; } }, [open]);
  if (!open || !reportTarget) return null;
  const isHighPriority = ["Child safety concern","Grooming","Sharing personal info","Attempting to move off-platform","Sexual content","Threats or violence","Self-harm or suicide"].includes(reason);
  async function submit() {
    if (!reason || saving || submitLockRef.current) return;
    submitLockRef.current = true;
    setSaving(true);
    setReportError("");
    const result = await fbAddReport(reporterUid || "anonymous", reportTarget, reason, detail, evidence).catch(() => ({ ok: false, error: "Submit failed. Try again." }));
    setSaving(false);
    if (!result.ok) { setReportError(result.error || "Submit failed. Try again."); submitLockRef.current = false; return; }
    setSubmitted(true);
  }
  return (
    <Modal open={open} onClose={onClose} width={420} title="Report member">
      {submitted ? (
        <div style={{ textAlign:"center", padding:"16px 0" }}>
          <div style={{display:"flex",justifyContent:"center",marginBottom:12}}><KDCheck size={48} animate={true}/></div>
          <div style={{ fontWeight:600, fontSize:16, color:T.text, marginBottom:6 }}>Report submitted</div>
          <div style={{ fontSize:13, color:T.textMuted, marginBottom:8 }}>Our moderation team will review @{reportTarget} within 24 hours.</div>
          {isHighPriority && <div style={{ fontSize:12, color:"#ef4444", background: T.isDark?"#1a0000":"#fff0f0", border:"1px solid #ef444440", borderRadius:8, padding:"8px 12px", marginBottom:12 }}>⚡ This report has been flagged as high priority and escalated immediately.</div>}
          <Btn onClick={onClose}>Close</Btn>
        </div>
      ) : (
        <>
          <div style={{ fontSize:13, color:T.textMuted, marginBottom:16 }}>
            Report <strong>@{reportTarget}</strong> for a violation. False reports may result in account suspension. All reports are reviewed by our moderation team.
          </div>
          {evidence?.messageText && (
            <div style={{ background:T.surfaceAlt, border:`1px solid ${T.border}`, borderRadius:8, padding:"8px 12px", marginBottom:14, fontSize:12, color:T.textMuted }}>
              <div style={{ fontWeight:600, marginBottom:4, color:T.text }}>Reported message:</div>
              <div style={{ fontStyle:"italic" }}>"{evidence.messageText.slice(0,120)}{evidence.messageText.length>120?"…":""}"</div>
            </div>
          )}
          <div style={{ fontSize:12, fontWeight:500, color:T.text, marginBottom:8 }}>Reason <span style={{color:"#ef4444"}}>*</span></div>
          <div style={{ display:"flex", flexDirection:"column", gap:5, marginBottom:14 }}>
            {REPORT_REASONS.map(r => {
              const isHigh = ["Child safety concern","Grooming","Sharing personal info","Attempting to move off-platform","Sexual content","Threats or violence","Self-harm or suicide"].includes(r);
              return (
                <label key={r} style={{ display:"flex", alignItems:"center", gap:9, padding:"7px 10px", borderRadius:8, background: reason===r ? (T.isDark?"rgba(245,200,0,0.1)":SHARED.yellowLight) : T.surfaceAlt, border:`1px solid ${reason===r ? SHARED.yellowBorder : T.border}`, cursor:"pointer", fontSize:13, color:T.text, transition:"all 0.12s" }}>
                  <input type="radio" name="report_reason" value={r} checked={reason===r} onChange={() => setReason(r)} style={{ accentColor:SHARED.yellow }} />
                  <span style={{flex:1}}>{r}</span>
                  {isHigh && <span style={{ fontSize:10, fontWeight:700, color:"#ef4444", background:"#ef444415", borderRadius:4, padding:"2px 6px" }}>HIGH</span>}
                </label>
              );
            })}
          </div>
          <div style={{ fontSize:12, fontWeight:500, color:T.text, marginBottom:6 }}>Additional details <span style={{ color:T.textFaint, fontWeight:400 }}>(optional)</span></div>
          <textarea
            value={detail}
            onChange={e => setDetail(e.target.value.slice(0,1000))}
            placeholder="Describe the issue in detail…"
            rows={3}
            style={{ width:"100%", background:T.surfaceAlt, border:`1px solid ${T.border}`, borderRadius:8, padding:"8px 12px", fontFamily:"inherit", fontSize:13, color:T.text, outline:"none", resize:"vertical", boxSizing:"border-box", marginBottom:14 }}
          />
          <div style={{ display:"flex", gap:8 }}>
            <Btn variant="danger" style={{ flex:1 }} onClick={submit} disabled={!reason || saving} loading={saving}>Submit report</Btn>
            <Btn variant="ghost" onClick={onClose}>Cancel</Btn>
          </div>
          {reportError && <div style={{ marginTop:8, fontSize:12, color:T.errorText }}>{reportError}</div>}
        </>
      )}
    </Modal>
  );
}

// Simulated "last submission time" per member (what would come from a real backend)

function RoomMemberStatusList({ members, userState, submittedToday, me, allUsers = [] }) {
  const { T } = useTheme();
  const presenceMap = usePresenceMap();
  const [reportTarget, setReportTarget] = useState(null);

  // Helper: look up a member's full profile from allUsers by their init or userId
  function lookupMember(init) {
    if (!init) return null;
    return allUsers.find(u =>
      (u.userId && (u.userId.slice(0,2).toUpperCase() === init || u.userId === init)) ||
      (u.displayName && u.displayName.slice(0,2).toUpperCase() === init)
    ) || null;
  }

  // Ensure current user (me) always appears in the list even if their
  // init isn't in members[] yet (e.g. just joined, membersList not yet synced).
  const memberInits = members || [];
  const meInit = me?.init;
  // Normalise comparison: both sides uppercased so "po" === "PO" never causes a dup
  const meAlreadyInList = !meInit || memberInits.some(init =>
    (init || "").toUpperCase() === (meInit || "").toUpperCase() ||
    (init || "").toUpperCase() === (me?.userId || "").toUpperCase().slice(0,2)
  );
  // Deduplicated list with current user always present
  // Also deduplicate the raw list itself in case the DB has duplicates
  const seen = new Set();
  const deduped = memberInits.filter(init => {
    const key = (init || "").toUpperCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  const displayMembers = meAlreadyInList
    ? deduped
    : [meInit, ...deduped];

  if (displayMembers.length === 0) {
    return <div style={{ fontSize: 12, color: T.textFaint, padding: "8px 0" }}>No members yet.</div>;
  }
  return (
    <>
    <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
      {displayMembers.slice(0, 8).map(init => {
        const isMe = me && (init === me.init || init === me.userId);
        const presence = presenceMap[init] || { online: false };
        const isOnline = isMe ? true : presence.online;
        const status = isMe
          ? (userState?.kickedFromRoom ? "kicked" : submittedToday ? "active" : userState?.missedDays >= 1 ? "at_risk" : "active")
          : "active";
        const dot = status === "kicked" ? "#ef4444" : status === "at_risk" ? "#f97316" : isOnline ? "#22c55e" : "#6b7280";
        const label = status === "kicked" ? "kicked" : status === "at_risk" ? "at risk" : isMe ? (submittedToday ? "submitted ✓" : "not yet") : isOnline ? "online" : "offline";

        // Look up full profile — for self use me directly, for others scan allUsers
        const profile = isMe ? null : lookupMember(init);
        const displayName = isMe
          ? (me.name || me.userId || init)
          : (profile?.displayName || profile?.userId || init);
        const username = isMe
          ? (me.userId || me.init || init)
          : (profile?.userId || init);
        // Avatar: use photo if available, else coloured initial circle
        const photo = isMe ? me.photo : (profile?.photo || null);
        const avatarColor = isMe ? (me.color || SHARED.yellow) : ("#" + (((username.charCodeAt(0)||65)*4567+1234)%0xFFFFFF).toString(16).padStart(6,"0"));

        return (
          <div key={init} style={{ display: "flex", alignItems: "center", gap: 8, padding: "7px 10px", background: T.surfaceAlt, borderRadius: 8 }}>
            {/* Online indicator dot */}
            <span style={{ width: 7, height: 7, borderRadius: "50%", background: dot, flexShrink: 0, boxShadow: isOnline && status !== "kicked" ? `0 0 5px ${dot}` : "none" }} />
            <Avatar name={displayName} photo={photo} size={26} color={SHARED.yellow} username={username} />
            {/* Name + username */}
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 12, fontWeight: isMe ? 700 : 500, color: T.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                {displayName}{isMe ? " (you)" : ""}
              </div>
              <div style={{ fontSize: 10, color: T.textFaint, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                @{username}
              </div>
            </div>
            <span style={{ fontSize: 11, color: T.textFaint, flexShrink: 0 }}>{label}</span>
            {/* Report button — only visible for other members, not self */}
            {!isMe && (
              <button
                onClick={() => setReportTarget(username || init)}
                title="Report member"
                style={{ background:"none", border:"none", cursor:"pointer", color:T.textFaint, fontSize:12, padding:"0 2px", flexShrink:0, lineHeight:1 }}
                onMouseEnter={e => { e.currentTarget.style.color = SHARED.red; }}
                onMouseLeave={e => { e.currentTarget.style.color = T.textFaint; }}
              >
                
              </button>
            )}
          </div>
        );
      })}
    </div>
    {/* FIX 3: pass me.uid as reporterUid so reports are attributed correctly */}
    <ReportUserModal open={!!reportTarget} onClose={() => setReportTarget(null)} reportTarget={reportTarget} reporterUid={me?.uid || me?.userId} />
    </>
  );
}


// ── SYSTEM 6: KICKED SCREEN + REJOIN FLOW ────────────────────────────────────
// Shown when userState.kickedFromRoom is true. Shows 24h cooldown before rejoin.
// ══════════════════════════════════════════════════════════════════════════════
function KickedScreen({ userState, onFindRoom, profile = {} }) {
  const { T } = useTheme();
  const [cooldownLeft, setCooldownLeft] = useState(null);

  useEffect(() => {
    // 24h cooldown from kick timestamp (stored in userState.kickedAt)
    function tick() {
      if (!userState.kickedAt) { setCooldownLeft(0); return; }
      const elapsed = Date.now() - new Date(userState.kickedAt).getTime();
      const remaining = Math.max(0, 86400000 - elapsed);
      setCooldownLeft(remaining);
    }
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [userState.kickedAt]);

  const canRejoin = cooldownLeft === 0;
  const h = Math.floor((cooldownLeft || 0) / 3600000);
  const m = Math.floor(((cooldownLeft || 0) % 3600000) / 60000);
  const s = Math.floor(((cooldownLeft || 0) % 60000) / 1000);
  const pad = n => String(n).padStart(2, "0");

  return (
    <div style={{ maxWidth: 600, margin: "60px 0", padding: "0 28px", textAlign: "left" }}>
      <div style={{display:"flex",justifyContent:"center",marginBottom:12}}><KDSkull size={64} animate={true}/></div>
      <div style={{ fontWeight: 700, fontSize: 24, color: T.text, marginBottom: 6 }}>You were removed</div>
      <div style={{ fontSize: 14, color: T.textMuted, marginBottom: 24, lineHeight: 1.6 }}>
        You missed 3 consecutive days and were auto-kicked from your room.<br />
        Your streak has been reset.
      </div>

      {/* Kick log entry */}
      <div style={{ background: T.errorBg, border: `1px solid ${T.errorBorder}`, borderRadius: 12, padding: "14px 18px", marginBottom: 24, textAlign: "left" }}>
        <div style={{ fontSize: 12, fontWeight: 600, color: T.errorText, marginBottom: 6, display: "flex", alignItems: "center", gap: 5 }}>{Icon.x} Kick record</div>
        {[
          ["Member",  profile.displayName],
          ["Reason",  "3 consecutive missed days"],
          ["Date",    new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })],
          ["Streak",  "Reset to 0"],
        ].map(([l, v]) => (
          <div key={l} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "6px 0", borderTop: `1px solid ${T.errorBorder}`, fontSize: 13, gap: 8 }}>
            <span style={{ color: "#991b1b", flexShrink: 0, minWidth: 60 }}>{l}</span>
            <span style={{ fontWeight: 500, color: T.errorText, textAlign: "right", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{v}</span>
          </div>
        ))}
      </div>

      {/* Cooldown / rejoin */}
      {!canRejoin ? (
        <div style={{ background: T.surfaceAlt, border: `1px solid ${T.border}`, borderRadius: 12, padding: "18px 20px", marginBottom: 20 }}>
          <div style={{ fontSize: 12, color: T.textMuted, marginBottom: 6 }}>Rejoin available in</div>
          <div style={{ fontSize: 36, fontWeight: 700, fontFamily: "monospace", color: T.text, letterSpacing: 2 }}>{pad(h)}:{pad(m)}:{pad(s)}</div>
          <div style={{ fontSize: 11, color: T.textFaint, marginTop: 4 }}>24-hour cooldown before you can join a new room</div>
        </div>
      ) : (
        <div style={{ background: T.successBg, border: `1px solid ${T.successBorder}`, borderRadius: 12, padding: "14px 18px", marginBottom: 20 }}>
          <div style={{ fontSize: 14, fontWeight: 500, color: T.successText, display:"flex", alignItems:"center", gap:5 }}><KDCheck size={16}/>Cooldown over — you can rejoin</div>
          <div style={{ fontSize: 12, color: T.successText, marginTop: 4 }}>Go through the AI interview again to prove your commitment.</div>
        </div>
      )}

      <Btn variant="primary" style={{ width: "100%", opacity: canRejoin ? 1 : 0.4 }} disabled={!canRejoin} onClick={canRejoin ? onFindRoom : undefined}>
        {canRejoin ? "Find a new room →" : "Come back later"}
      </Btn>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// ── SYSTEM 7: AI NUDGE SYSTEM ─────────────────────────────────────────────────
// Short, direct Claude-generated nudges based on current streak status.
// Fetches one nudge on mount/status-change, caches it for the session.
// ══════════════════════════════════════════════════════════════════════════════
function useAINudge(userState, submittedToday) {
  const [nudge, setNudge] = useState(null);
  const [loading, setLoading] = useState(false);
  const prevStatusRef = useRef(null);

  useEffect(() => {
    const status = `${userState?.kickStatus}_${submittedToday}_${userState?.streak}`;
    if (status === prevStatusRef.current) return; // don't re-fetch same state
    if (submittedToday) { setNudge(null); prevStatusRef.current = status; return; }
    if (!userState || userState.kickStatus === "ok" && userState.missedDays === 0) {
      setNudge(null); prevStatusRef.current = status; return;
    }

    prevStatusRef.current = status;
    setLoading(true);
    let active = true; // cleanup flag

    const prompts = {
      kicked:  "The user was kicked for missing 3 days. Write 1 short direct sentence max 12 words to motivate return. No emojis.",
      at_risk: "The user missed 2 days. Write 1 blunt warning sentence max 12 words. No softening. No emojis.",
      flagged: "User hasn't submitted today. Write 1 urgent reminder max 10 words. Direct. No emojis.",
    };
    const fallbacks = {
      kicked:  "You failed. The only move now is to come back harder.",
      at_risk: "Miss one more day and you're out. No exceptions.",
      flagged: "You haven't submitted today. You're at risk.",
    };
    const prompt = prompts[userState.kickStatus] || prompts.flagged;

    callClaude([{ role: "user", content: prompt }],
      "You are Kick, a ruthless accountability AI. One sentence only. No fluff. No emojis.",
      80
    ).then(text => {
      if (!active) return;
      setNudge(text.trim().replace(/^"|"$/g, "") || fallbacks[userState.kickStatus] || fallbacks.flagged);
      setLoading(false);
    }).catch(() => {
      if (!active) return;
      setNudge(fallbacks[userState.kickStatus] || fallbacks.flagged);
      setLoading(false);
    });
    return () => { active = false; };
  }, [userState?.kickStatus, userState?.missedDays, submittedToday]);

  return { nudge, loading };
}

function AINudgeBanner({ userState, submittedToday }) {
  const { T } = useTheme();
  const { nudge, loading } = useAINudge(userState, submittedToday);

  if (submittedToday || !nudge && !loading) return null;

  const isKicked = userState?.kickStatus === "kicked";
  const isAtRisk = userState?.kickStatus === "at_risk";

  const bg     = isKicked ? "#0f0f0f" : isAtRisk ? "#1a0a00" : T.bg === "#0f0f0f" ? "#1a1a00" : "#111";
  const color  = isKicked ? SHARED.red : isAtRisk ? "#fb923c" : SHARED.yellow;

  return (
    <div style={{ background: bg, borderRadius: 10, padding: "12px 16px", marginBottom: 14, display: "flex", alignItems: "flex-start", gap: 10 }}>
      <Wolf size={22} variant="dark" />
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: 10, fontWeight: 600, color: "#555", textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 3 }}>Kick AI</div>
        {loading
          ? <div style={{ fontSize: 13, color: "#555", letterSpacing: 3 }}>···</div>
          : <div style={{ fontSize: 14, fontWeight: 500, color, lineHeight: 1.5 }}>{nudge}</div>}
      </div>
    </div>
  );
}


