      <div style={{ display: "flex", gap: 8 }}>
        <Btn variant="danger" style={{ flex: 1 }} onClick={onConfirm}>Leave room</Btn>
        <Btn variant="ghost" style={{ flex: 1 }} onClick={onClose}>Stay in</Btn>
      </div>
